const textAssets = {"/":{"body":"<!doctype html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <meta name=\"theme-color\" content=\"#e9e7df\" />\r\n\r\n    <title>ETC Weather Observation</title>\r\n    <meta\r\n      name=\"description\"\r\n      content=\"ETC Weather Observation is a Carnegie Mellon Entertainment Technology Center project. Read the weather packet archive and watch the countdown to the next update bulletin.\"\r\n    />\r\n    <link rel=\"canonical\" href=\"https://etcweatherobservation.com/\" />\r\n    <meta name=\"robots\" content=\"index, follow, max-image-preview:large\" />\r\n\r\n    <meta property=\"og:type\" content=\"website\" />\r\n    <meta property=\"og:site_name\" content=\"ETC Weather Observation\" />\r\n    <meta property=\"og:title\" content=\"ETC Weather Observation\" />\r\n    <meta\r\n      property=\"og:description\"\r\n      content=\"A Carnegie Mellon Entertainment Technology Center project. Weather packet archive and a live countdown to the next update bulletin.\"\r\n    />\r\n    <meta property=\"og:url\" content=\"https://etcweatherobservation.com/\" />\r\n    <meta property=\"og:locale\" content=\"en_US\" />\r\n    <meta property=\"og:image\" content=\"https://etcweatherobservation.com/og.png\" />\r\n    <meta property=\"og:image:width\" content=\"1200\" />\r\n    <meta property=\"og:image:height\" content=\"630\" />\r\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\r\n    <meta name=\"twitter:image\" content=\"https://etcweatherobservation.com/og.png\" />\r\n\r\n    <script type=\"application/ld+json\">\r\n      {\r\n        \"@context\": \"https://schema.org\",\r\n        \"@type\": \"WebSite\",\r\n        \"name\": \"ETC Weather Observation\",\r\n        \"url\": \"https://etcweatherobservation.com/\",\r\n        \"description\": \"A Carnegie Mellon Entertainment Technology Center project. Weather packet archive and a live countdown to the next update bulletin.\",\r\n        \"inLanguage\": \"en\"\r\n      }\r\n    </script>\r\n\r\n    <link rel=\"icon\" href=\"./icon_black.ico\" media=\"(prefers-color-scheme: light)\" sizes=\"any\" />\r\n    <link rel=\"icon\" href=\"./icon_white.ico\" media=\"(prefers-color-scheme: dark)\" sizes=\"any\" />\r\n    <link rel=\"stylesheet\" href=\"./style.css\" />\r\n  </head>\r\n  <body>\r\n    <div class=\"paper-grain\" aria-hidden=\"true\"></div>\r\n\r\n    <aside class=\"site-nav\" aria-label=\"Observation sections\">\r\n      <div class=\"nav-scan\" aria-hidden=\"true\"></div>\r\n      <div class=\"site-nav__identity\">\r\n        <span class=\"site-nav__mark\"><img src=\"./fish_black.png\" alt=\"\" /><b>ETC</b></span>\r\n        <span class=\"site-nav__name\">WEATHER<br />OBSERVATION</span>\r\n        <span class=\"site-nav__hint\" aria-hidden=\"true\">EXPAND&nbsp;›</span>\r\n      </div>\r\n      <nav>\r\n        <button class=\"site-nav__item is-active\" data-route=\"current\" data-label=\"CURRENT\" type=\"button\">\r\n          <span class=\"nav-index\">01</span><span class=\"nav-icon\" aria-hidden=\"true\">⌂</span><span class=\"nav-label\">CURRENT</span><span class=\"nav-arrow\">↗</span>\r\n        </button>\r\n        <button class=\"site-nav__item\" data-route=\"archive\" data-label=\"ARCHIVE\" type=\"button\">\r\n          <span class=\"nav-index\">02</span><span class=\"nav-icon\" aria-hidden=\"true\">▤</span><span class=\"nav-label\">ARCHIVE</span><span class=\"nav-arrow\">↗</span>\r\n        </button>\r\n        <button class=\"site-nav__item\" data-route=\"about\" data-label=\"ABOUT\" type=\"button\">\n          <span class=\"nav-index\">03</span><span class=\"nav-icon\" aria-hidden=\"true\">i</span><span class=\"nav-label\">ABOUT</span><span class=\"nav-arrow\">↗</span>\n        </button>\r\n      </nav>\r\n      <div class=\"site-nav__footer\">\r\n        <p class=\"site-nav__status\"><i></i><span>STATION ONLINE</span></p>\r\n        <p class=\"site-nav__coord\">40.4433°N<br />79.9436°W</p>\r\n      </div>\r\n    </aside>\r\n\r\n    <main class=\"sheet app-main\">\r\n      <i class=\"registration registration--tl\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--tc\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--tr\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--bl\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--bc\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--br\" aria-hidden=\"true\"></i>\r\n\r\n      <section class=\"bulletin view is-active\" data-view=\"current\" aria-labelledby=\"countdown-title\">\r\n        <header class=\"masthead\">\r\n          <div>\r\n            <p class=\"eyebrow\">T-00 / TEMPORAL OBSERVATION</p>\r\n            <h1 id=\"countdown-title\">NEXT UPDATE BULLETIN</h1>\r\n          </div>\r\n        </header>\r\n\r\n        <div class=\"rule rule--heavy\" aria-hidden=\"true\"></div>\r\n\r\n        <div class=\"metadata\" aria-label=\"Countdown metadata\">\r\n          <p>STATION: <strong>LOCAL</strong></p>\r\n          <p>PACKET: <strong id=\"packet-id\">0008</strong></p>\r\n          <p>ISSUED: <strong id=\"issued-date\">09/16/2026</strong></p>\n          <p>STATUS: <strong id=\"status-label\">SUSPENDED</strong></p>\n        </div>\n\n        <section class=\"countdown-panel\" aria-label=\"Suspended bulletin status\">\n          <p class=\"target-kicker\">NEXT UPDATE IN</p>\n\n          <div class=\"timer\" aria-label=\"Next update bulletin suspended\">\n            <div class=\"time-unit time-unit--hours\">\r\n              <span class=\"time-value\" id=\"hours\">00</span>\r\n              <span class=\"unit-label\">HOURS</span>\r\n            </div>\r\n            <div class=\"time-unit\">\r\n              <span class=\"time-value\" id=\"minutes\">00</span>\r\n              <span class=\"unit-label\">MINUTES</span>\r\n            </div>\r\n            <div class=\"time-unit\">\r\n              <span class=\"time-value\" id=\"seconds\">00</span>\r\n              <span class=\"unit-label\">SECONDS</span>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"target-line\" aria-label=\"Target date\">\r\n            <span class=\"target-line__label\">TARGET</span>\r\n            <span class=\"target-line__value\" id=\"target-display\">NOT SCHEDULED</span>\n          </div>\n        </section>\n\n        <a class=\"bulletin-alert\" href=\"#archive\">\n          <span class=\"bulletin-alert__status\">EMERGENCY NOTICE</span>\n          <span class=\"bulletin-alert__message\">BULLETIN SERVICE HAS BEEN SUSPENDED DUE TO AN EMERGENCY.</span>\n          <span class=\"bulletin-alert__action\">FOR AVAILABLE INFORMATION, PROCEED TO THE ARCHIVE AND REVIEW PREVIOUS PACKETS. <b>OPEN ARCHIVE&nbsp;↗</b></span>\n        </a>\n\n        <footer class=\"footer-line\">\n          <p>DATA FEED: LOCAL / SYNC: <span id=\"sync-state\">HALTED</span></p>\n          <p>CHK: <span id=\"checksum\">0000-0000</span></p>\r\n        </footer>\r\n      </section>\r\n\r\n      <section class=\"view console-view\" data-view=\"archive\" aria-labelledby=\"archive-title\">\r\n        <header class=\"view-head\"><p class=\"eyebrow\">PACKET RECORDS / LOCAL</p><h1 id=\"archive-title\">WEATHER PACKET ARCHIVE</h1><p class=\"view-code\" id=\"archive-code\">08 RECORDS / READ ONLY</p></header>\r\n        <div class=\"rule rule--heavy\"></div>\r\n        <nav class=\"archive-list\" id=\"archive-list\" aria-label=\"Weather packet archive\"></nav>\r\n        <p class=\"archive-note\" id=\"archive-note\">TWO RECORDS WITHHELD / OPERATOR ACCESS REQUIRED</p>\r\n      </section>\r\n\r\n      <section class=\"view console-view about-view\" data-view=\"about\" aria-labelledby=\"about-title\">\r\n        <header class=\"view-head\"><p class=\"eyebrow\">PUBLIC INFORMATION / ETC</p><h1 id=\"about-title\">ABOUT</h1><p class=\"view-code\">FILE / 00-A</p></header>\r\n        <div class=\"rule rule--heavy\"></div>\r\n        <div class=\"about-minimal\">\r\n          <p class=\"about-minimal__index\">00—A<br /><span>PUBLIC FILE</span></p>\r\n          <div class=\"about-minimal__copy\">\r\n            <p>ETC Weather Observation is an observation station established in response to the current exceptional conditions. It is intended to deliver the latest available information to students of the Entertainment Technology Center.</p>\r\n            <p>Please monitor each update. We will move through this period together.</p>\r\n          </div>\r\n          <footer>\r\n            <span><i></i> STATION ACTIVE</span>\r\n            <span>ETC / PITTSBURGH / 2026</span>\r\n          </footer>\r\n        </div>\r\n\r\n        <section class=\"affiliation\" id=\"affiliation\" aria-labelledby=\"affiliation-title\">\r\n          <p class=\"affiliation__index\">00—B<br /><span>OPERATOR FILE</span></p>\r\n          <div class=\"affiliation__panel\">\r\n            <h2 id=\"affiliation-title\">INTERNAL ARCHIVE ACCESS</h2>\r\n            <p class=\"affiliation__deck\">Restricted historical records are available to ETC affiliates.</p>\r\n\r\n            <form\r\n              class=\"email-form\"\r\n              id=\"affiliation-form\"\r\n              action=\"https://formspree.io/f/xzebzavr\"\r\n              method=\"post\"\r\n              novalidate\r\n            >\r\n              <label for=\"affiliation-andrew-id\">ANDREW ID</label>\r\n              <div class=\"email-form__entry\">\r\n                <div class=\"email-address\">\r\n                  <input\r\n                    id=\"affiliation-andrew-id\"\r\n                    type=\"text\"\r\n                    inputmode=\"email\"\r\n                    autocomplete=\"username\"\r\n                    autocapitalize=\"none\"\r\n                    spellcheck=\"false\"\r\n                    maxlength=\"64\"\r\n                    pattern=\"[A-Za-z0-9._+-]+\"\r\n                    aria-describedby=\"affiliation-status\"\r\n                    placeholder=\"AndrewID\"\r\n                    required\r\n                  />\r\n                  <span class=\"email-domain\">@andrew.cmu.edu</span>\r\n                </div>\r\n                <button class=\"submit-button\" type=\"submit\">VERIFY AFFILIATION</button>\r\n              </div>\r\n              <p class=\"email-form__status\" id=\"affiliation-status\" role=\"status\" aria-live=\"polite\"></p>\r\n            </form>\r\n\r\n            <div class=\"affiliation__result\" id=\"affiliation-result\" hidden>\r\n              <p class=\"affiliation__confirm\">ETC AFFILIATION CONFIRMED</p>\r\n              <dl class=\"affiliation__fields\">\r\n                <div><dt>USERNAME</dt><dd id=\"affiliation-username\">—</dd></div>\r\n                <div><dt>ARCHIVE ACCESS KEY</dt><dd id=\"affiliation-key\">—</dd></div>\r\n              </dl>\r\n              <p class=\"affiliation__hint\">Use this key to access restricted archive records.</p>\r\n            </div>\r\n          </div>\r\n        </section>\r\n      </section>\r\n\r\n      <p class=\"side-note\" aria-hidden=\"true\">ETC / OBSERVATION SERIES / 2026</p>\r\n    </main>\r\n\r\n    <dialog class=\"packet-viewer\" id=\"packet-viewer\" aria-labelledby=\"packet-viewer-title\">\r\n      <div class=\"packet-viewer__card\">\r\n        <header class=\"packet-dialog__head\">\r\n          <div>\r\n            <p class=\"eyebrow\" id=\"packet-viewer-meta\">PACKET RECORD</p>\r\n            <h2 id=\"packet-viewer-title\">WEATHER BULLETIN</h2>\r\n          </div>\r\n          <button class=\"packet-dialog__close\" id=\"packet-viewer-close\" type=\"button\" aria-label=\"Close packet\">✕</button>\r\n        </header>\r\n        <div class=\"packet-viewer__pages\" id=\"packet-viewer-pages\"></div>\r\n      </div>\r\n    </dialog>\r\n\r\n    <dialog class=\"restricted-dialog\" id=\"restricted-dialog\" aria-labelledby=\"restricted-title\">\r\n      <div class=\"restricted-dialog__card\">\r\n        <header class=\"packet-dialog__head\">\r\n          <p class=\"eyebrow\">RESTRICTED ARCHIVE</p>\r\n          <button class=\"packet-dialog__close\" id=\"restricted-close\" type=\"button\" aria-label=\"Close restricted archive\">✕</button>\r\n        </header>\r\n        <h2 id=\"restricted-title\">OPERATOR ACCESS REQUIRED</h2>\r\n        <p class=\"restricted-dialog__packet\" id=\"restricted-packet\">PACKETS 0001–0002 / WITHHELD</p>\r\n        <form id=\"archive-form\" class=\"archive-form\">\r\n          <label for=\"archive-key\">ACCESS KEY</label>\r\n          <div class=\"restricted-entry\"><input id=\"archive-key\" type=\"text\" autocomplete=\"off\" autocapitalize=\"characters\" spellcheck=\"false\" required /></div>\r\n          <button class=\"restricted-access\" type=\"submit\">UNLOCK ARCHIVE</button>\r\n          <p id=\"archive-status\" role=\"status\" aria-live=\"polite\"></p>\r\n        </form>\r\n      </div>\r\n    </dialog>\r\n\r\n    <dialog class=\"signal\" id=\"signal-dialog\" aria-labelledby=\"signal-title\">\r\n      <div class=\"signal__card\">\r\n        <header class=\"signal__head\">\r\n          <p class=\"eyebrow\" id=\"signal-title\">INCOMING / SOURCE UNRESOLVED</p>\r\n          <button class=\"signal__dismiss\" id=\"signal-dismiss\" type=\"button\" aria-label=\"Connection active\" disabled>\r\n            <span class=\"signal__dots\" aria-hidden=\"true\"><i></i><i></i><i></i></span>\r\n            <span class=\"signal__close\" aria-hidden=\"true\">×</span>\n          </button>\r\n        </header>\r\n        <div class=\"rule rule--heavy\" aria-hidden=\"true\"></div>\r\n        <div class=\"signal__body\" id=\"signal-body\" aria-live=\"polite\">\r\n          <p class=\"signal__question\" id=\"signal-question\">CAN YOU SEE THIS?</p>\r\n        </div>\r\n        <div class=\"signal__actions\" id=\"signal-actions\">\r\n          <button class=\"signal__yes\" id=\"signal-yes\" type=\"button\">YES</button>\r\n        </div>\r\n      </div>\r\n    </dialog>\r\n\r\n    <noscript>This observation console needs JavaScript to run.</noscript>\r\n    <script type=\"module\" src=\"./script.js\"></script>\r\n  </body>\r\n</html>\r\n","type":"text/html; charset=utf-8"},"/index.html":{"body":"<!doctype html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <meta name=\"theme-color\" content=\"#e9e7df\" />\r\n\r\n    <title>ETC Weather Observation</title>\r\n    <meta\r\n      name=\"description\"\r\n      content=\"ETC Weather Observation is a Carnegie Mellon Entertainment Technology Center project. Read the weather packet archive and watch the countdown to the next update bulletin.\"\r\n    />\r\n    <link rel=\"canonical\" href=\"https://etcweatherobservation.com/\" />\r\n    <meta name=\"robots\" content=\"index, follow, max-image-preview:large\" />\r\n\r\n    <meta property=\"og:type\" content=\"website\" />\r\n    <meta property=\"og:site_name\" content=\"ETC Weather Observation\" />\r\n    <meta property=\"og:title\" content=\"ETC Weather Observation\" />\r\n    <meta\r\n      property=\"og:description\"\r\n      content=\"A Carnegie Mellon Entertainment Technology Center project. Weather packet archive and a live countdown to the next update bulletin.\"\r\n    />\r\n    <meta property=\"og:url\" content=\"https://etcweatherobservation.com/\" />\r\n    <meta property=\"og:locale\" content=\"en_US\" />\r\n    <meta property=\"og:image\" content=\"https://etcweatherobservation.com/og.png\" />\r\n    <meta property=\"og:image:width\" content=\"1200\" />\r\n    <meta property=\"og:image:height\" content=\"630\" />\r\n    <meta name=\"twitter:card\" content=\"summary_large_image\" />\r\n    <meta name=\"twitter:image\" content=\"https://etcweatherobservation.com/og.png\" />\r\n\r\n    <script type=\"application/ld+json\">\r\n      {\r\n        \"@context\": \"https://schema.org\",\r\n        \"@type\": \"WebSite\",\r\n        \"name\": \"ETC Weather Observation\",\r\n        \"url\": \"https://etcweatherobservation.com/\",\r\n        \"description\": \"A Carnegie Mellon Entertainment Technology Center project. Weather packet archive and a live countdown to the next update bulletin.\",\r\n        \"inLanguage\": \"en\"\r\n      }\r\n    </script>\r\n\r\n    <link rel=\"icon\" href=\"./icon_black.ico\" media=\"(prefers-color-scheme: light)\" sizes=\"any\" />\r\n    <link rel=\"icon\" href=\"./icon_white.ico\" media=\"(prefers-color-scheme: dark)\" sizes=\"any\" />\r\n    <link rel=\"stylesheet\" href=\"./style.css\" />\r\n  </head>\r\n  <body>\r\n    <div class=\"paper-grain\" aria-hidden=\"true\"></div>\r\n\r\n    <aside class=\"site-nav\" aria-label=\"Observation sections\">\r\n      <div class=\"nav-scan\" aria-hidden=\"true\"></div>\r\n      <div class=\"site-nav__identity\">\r\n        <span class=\"site-nav__mark\"><img src=\"./fish_black.png\" alt=\"\" /><b>ETC</b></span>\r\n        <span class=\"site-nav__name\">WEATHER<br />OBSERVATION</span>\r\n        <span class=\"site-nav__hint\" aria-hidden=\"true\">EXPAND&nbsp;›</span>\r\n      </div>\r\n      <nav>\r\n        <button class=\"site-nav__item is-active\" data-route=\"current\" data-label=\"CURRENT\" type=\"button\">\r\n          <span class=\"nav-index\">01</span><span class=\"nav-icon\" aria-hidden=\"true\">⌂</span><span class=\"nav-label\">CURRENT</span><span class=\"nav-arrow\">↗</span>\r\n        </button>\r\n        <button class=\"site-nav__item\" data-route=\"archive\" data-label=\"ARCHIVE\" type=\"button\">\r\n          <span class=\"nav-index\">02</span><span class=\"nav-icon\" aria-hidden=\"true\">▤</span><span class=\"nav-label\">ARCHIVE</span><span class=\"nav-arrow\">↗</span>\r\n        </button>\r\n        <button class=\"site-nav__item\" data-route=\"about\" data-label=\"ABOUT\" type=\"button\">\n          <span class=\"nav-index\">03</span><span class=\"nav-icon\" aria-hidden=\"true\">i</span><span class=\"nav-label\">ABOUT</span><span class=\"nav-arrow\">↗</span>\n        </button>\r\n      </nav>\r\n      <div class=\"site-nav__footer\">\r\n        <p class=\"site-nav__status\"><i></i><span>STATION ONLINE</span></p>\r\n        <p class=\"site-nav__coord\">40.4433°N<br />79.9436°W</p>\r\n      </div>\r\n    </aside>\r\n\r\n    <main class=\"sheet app-main\">\r\n      <i class=\"registration registration--tl\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--tc\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--tr\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--bl\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--bc\" aria-hidden=\"true\"></i>\r\n      <i class=\"registration registration--br\" aria-hidden=\"true\"></i>\r\n\r\n      <section class=\"bulletin view is-active\" data-view=\"current\" aria-labelledby=\"countdown-title\">\r\n        <header class=\"masthead\">\r\n          <div>\r\n            <p class=\"eyebrow\">T-00 / TEMPORAL OBSERVATION</p>\r\n            <h1 id=\"countdown-title\">NEXT UPDATE BULLETIN</h1>\r\n          </div>\r\n        </header>\r\n\r\n        <div class=\"rule rule--heavy\" aria-hidden=\"true\"></div>\r\n\r\n        <div class=\"metadata\" aria-label=\"Countdown metadata\">\r\n          <p>STATION: <strong>LOCAL</strong></p>\r\n          <p>PACKET: <strong id=\"packet-id\">0008</strong></p>\r\n          <p>ISSUED: <strong id=\"issued-date\">09/16/2026</strong></p>\n          <p>STATUS: <strong id=\"status-label\">SUSPENDED</strong></p>\n        </div>\n\n        <section class=\"countdown-panel\" aria-label=\"Suspended bulletin status\">\n          <p class=\"target-kicker\">NEXT UPDATE IN</p>\n\n          <div class=\"timer\" aria-label=\"Next update bulletin suspended\">\n            <div class=\"time-unit time-unit--hours\">\r\n              <span class=\"time-value\" id=\"hours\">00</span>\r\n              <span class=\"unit-label\">HOURS</span>\r\n            </div>\r\n            <div class=\"time-unit\">\r\n              <span class=\"time-value\" id=\"minutes\">00</span>\r\n              <span class=\"unit-label\">MINUTES</span>\r\n            </div>\r\n            <div class=\"time-unit\">\r\n              <span class=\"time-value\" id=\"seconds\">00</span>\r\n              <span class=\"unit-label\">SECONDS</span>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"target-line\" aria-label=\"Target date\">\r\n            <span class=\"target-line__label\">TARGET</span>\r\n            <span class=\"target-line__value\" id=\"target-display\">NOT SCHEDULED</span>\n          </div>\n        </section>\n\n        <a class=\"bulletin-alert\" href=\"#archive\">\n          <span class=\"bulletin-alert__status\">EMERGENCY NOTICE</span>\n          <span class=\"bulletin-alert__message\">BULLETIN SERVICE HAS BEEN SUSPENDED DUE TO AN EMERGENCY.</span>\n          <span class=\"bulletin-alert__action\">FOR AVAILABLE INFORMATION, PROCEED TO THE ARCHIVE AND REVIEW PREVIOUS PACKETS. <b>OPEN ARCHIVE&nbsp;↗</b></span>\n        </a>\n\n        <footer class=\"footer-line\">\n          <p>DATA FEED: LOCAL / SYNC: <span id=\"sync-state\">HALTED</span></p>\n          <p>CHK: <span id=\"checksum\">0000-0000</span></p>\r\n        </footer>\r\n      </section>\r\n\r\n      <section class=\"view console-view\" data-view=\"archive\" aria-labelledby=\"archive-title\">\r\n        <header class=\"view-head\"><p class=\"eyebrow\">PACKET RECORDS / LOCAL</p><h1 id=\"archive-title\">WEATHER PACKET ARCHIVE</h1><p class=\"view-code\" id=\"archive-code\">08 RECORDS / READ ONLY</p></header>\r\n        <div class=\"rule rule--heavy\"></div>\r\n        <nav class=\"archive-list\" id=\"archive-list\" aria-label=\"Weather packet archive\"></nav>\r\n        <p class=\"archive-note\" id=\"archive-note\">TWO RECORDS WITHHELD / OPERATOR ACCESS REQUIRED</p>\r\n      </section>\r\n\r\n      <section class=\"view console-view about-view\" data-view=\"about\" aria-labelledby=\"about-title\">\r\n        <header class=\"view-head\"><p class=\"eyebrow\">PUBLIC INFORMATION / ETC</p><h1 id=\"about-title\">ABOUT</h1><p class=\"view-code\">FILE / 00-A</p></header>\r\n        <div class=\"rule rule--heavy\"></div>\r\n        <div class=\"about-minimal\">\r\n          <p class=\"about-minimal__index\">00—A<br /><span>PUBLIC FILE</span></p>\r\n          <div class=\"about-minimal__copy\">\r\n            <p>ETC Weather Observation is an observation station established in response to the current exceptional conditions. It is intended to deliver the latest available information to students of the Entertainment Technology Center.</p>\r\n            <p>Please monitor each update. We will move through this period together.</p>\r\n          </div>\r\n          <footer>\r\n            <span><i></i> STATION ACTIVE</span>\r\n            <span>ETC / PITTSBURGH / 2026</span>\r\n          </footer>\r\n        </div>\r\n\r\n        <section class=\"affiliation\" id=\"affiliation\" aria-labelledby=\"affiliation-title\">\r\n          <p class=\"affiliation__index\">00—B<br /><span>OPERATOR FILE</span></p>\r\n          <div class=\"affiliation__panel\">\r\n            <h2 id=\"affiliation-title\">INTERNAL ARCHIVE ACCESS</h2>\r\n            <p class=\"affiliation__deck\">Restricted historical records are available to ETC affiliates.</p>\r\n\r\n            <form\r\n              class=\"email-form\"\r\n              id=\"affiliation-form\"\r\n              action=\"https://formspree.io/f/xzebzavr\"\r\n              method=\"post\"\r\n              novalidate\r\n            >\r\n              <label for=\"affiliation-andrew-id\">ANDREW ID</label>\r\n              <div class=\"email-form__entry\">\r\n                <div class=\"email-address\">\r\n                  <input\r\n                    id=\"affiliation-andrew-id\"\r\n                    type=\"text\"\r\n                    inputmode=\"email\"\r\n                    autocomplete=\"username\"\r\n                    autocapitalize=\"none\"\r\n                    spellcheck=\"false\"\r\n                    maxlength=\"64\"\r\n                    pattern=\"[A-Za-z0-9._+-]+\"\r\n                    aria-describedby=\"affiliation-status\"\r\n                    placeholder=\"AndrewID\"\r\n                    required\r\n                  />\r\n                  <span class=\"email-domain\">@andrew.cmu.edu</span>\r\n                </div>\r\n                <button class=\"submit-button\" type=\"submit\">VERIFY AFFILIATION</button>\r\n              </div>\r\n              <p class=\"email-form__status\" id=\"affiliation-status\" role=\"status\" aria-live=\"polite\"></p>\r\n            </form>\r\n\r\n            <div class=\"affiliation__result\" id=\"affiliation-result\" hidden>\r\n              <p class=\"affiliation__confirm\">ETC AFFILIATION CONFIRMED</p>\r\n              <dl class=\"affiliation__fields\">\r\n                <div><dt>USERNAME</dt><dd id=\"affiliation-username\">—</dd></div>\r\n                <div><dt>ARCHIVE ACCESS KEY</dt><dd id=\"affiliation-key\">—</dd></div>\r\n              </dl>\r\n              <p class=\"affiliation__hint\">Use this key to access restricted archive records.</p>\r\n            </div>\r\n          </div>\r\n        </section>\r\n      </section>\r\n\r\n      <p class=\"side-note\" aria-hidden=\"true\">ETC / OBSERVATION SERIES / 2026</p>\r\n    </main>\r\n\r\n    <dialog class=\"packet-viewer\" id=\"packet-viewer\" aria-labelledby=\"packet-viewer-title\">\r\n      <div class=\"packet-viewer__card\">\r\n        <header class=\"packet-dialog__head\">\r\n          <div>\r\n            <p class=\"eyebrow\" id=\"packet-viewer-meta\">PACKET RECORD</p>\r\n            <h2 id=\"packet-viewer-title\">WEATHER BULLETIN</h2>\r\n          </div>\r\n          <button class=\"packet-dialog__close\" id=\"packet-viewer-close\" type=\"button\" aria-label=\"Close packet\">✕</button>\r\n        </header>\r\n        <div class=\"packet-viewer__pages\" id=\"packet-viewer-pages\"></div>\r\n      </div>\r\n    </dialog>\r\n\r\n    <dialog class=\"restricted-dialog\" id=\"restricted-dialog\" aria-labelledby=\"restricted-title\">\r\n      <div class=\"restricted-dialog__card\">\r\n        <header class=\"packet-dialog__head\">\r\n          <p class=\"eyebrow\">RESTRICTED ARCHIVE</p>\r\n          <button class=\"packet-dialog__close\" id=\"restricted-close\" type=\"button\" aria-label=\"Close restricted archive\">✕</button>\r\n        </header>\r\n        <h2 id=\"restricted-title\">OPERATOR ACCESS REQUIRED</h2>\r\n        <p class=\"restricted-dialog__packet\" id=\"restricted-packet\">PACKETS 0001–0002 / WITHHELD</p>\r\n        <form id=\"archive-form\" class=\"archive-form\">\r\n          <label for=\"archive-key\">ACCESS KEY</label>\r\n          <div class=\"restricted-entry\"><input id=\"archive-key\" type=\"text\" autocomplete=\"off\" autocapitalize=\"characters\" spellcheck=\"false\" required /></div>\r\n          <button class=\"restricted-access\" type=\"submit\">UNLOCK ARCHIVE</button>\r\n          <p id=\"archive-status\" role=\"status\" aria-live=\"polite\"></p>\r\n        </form>\r\n      </div>\r\n    </dialog>\r\n\r\n    <dialog class=\"signal\" id=\"signal-dialog\" aria-labelledby=\"signal-title\">\r\n      <div class=\"signal__card\">\r\n        <header class=\"signal__head\">\r\n          <p class=\"eyebrow\" id=\"signal-title\">INCOMING / SOURCE UNRESOLVED</p>\r\n          <button class=\"signal__dismiss\" id=\"signal-dismiss\" type=\"button\" aria-label=\"Connection active\" disabled>\r\n            <span class=\"signal__dots\" aria-hidden=\"true\"><i></i><i></i><i></i></span>\r\n            <span class=\"signal__close\" aria-hidden=\"true\">×</span>\n          </button>\r\n        </header>\r\n        <div class=\"rule rule--heavy\" aria-hidden=\"true\"></div>\r\n        <div class=\"signal__body\" id=\"signal-body\" aria-live=\"polite\">\r\n          <p class=\"signal__question\" id=\"signal-question\">CAN YOU SEE THIS?</p>\r\n        </div>\r\n        <div class=\"signal__actions\" id=\"signal-actions\">\r\n          <button class=\"signal__yes\" id=\"signal-yes\" type=\"button\">YES</button>\r\n        </div>\r\n      </div>\r\n    </dialog>\r\n\r\n    <noscript>This observation console needs JavaScript to run.</noscript>\r\n    <script type=\"module\" src=\"./script.js\"></script>\r\n  </body>\r\n</html>\r\n","type":"text/html; charset=utf-8"},"/style.css":{"body":":root {\r\n  --rail-width: 76px;\r\n  --paper: #e9e7df;\r\n  --paper-bright: #f1efe8;\r\n  --ink: #111210;\r\n  --ink-soft: rgba(17, 18, 16, 0.56);\r\n  --line: rgba(17, 18, 16, 0.44);\r\n  --hairline: rgba(17, 18, 16, 0.2);\r\n  --mono: 'Cascadia Mono', 'SFMono-Regular', 'Noto Sans Mono CJK SC', 'Courier New', monospace;\r\n  --sans: 'Helvetica Neue', 'Segoe UI', Arial, sans-serif;\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\nhtml {\r\n  background: #c9c7bf;\r\n  color: var(--ink);\r\n  font-family: var(--mono);\r\n}\r\n\r\nbody {\r\n  min-width: 320px;\r\n  min-height: 100vh;\r\n  margin: 0;\r\n  background:\r\n    radial-gradient(circle at 50% -20%, rgba(255, 255, 255, 0.7), transparent 52%),\r\n    #c9c7bf;\r\n}\r\n\r\nbutton,\r\ninput {\r\n  font: inherit;\r\n}\r\n\r\nbutton {\r\n  color: inherit;\r\n}\r\n\r\n.site-nav { position: fixed; inset: 0 auto 0 0; z-index: 20; display: flex; width: 230px; padding: 2rem 1.4rem; flex-direction: column; border-right: 1px solid var(--ink); background: rgba(233,231,223,.94); backdrop-filter: blur(10px); }\r\n.site-nav__identity { display: flex; align-items: center; gap: .8rem; font-size: .62rem; letter-spacing: .1em; line-height: 1.45; }\r\n.site-nav__mark { position: relative; display: grid; width: 46px; height: 46px; place-items: center; border: 0; }\r\n.site-nav__mark img { display: block; width: 38px; height: 41px; object-fit: contain; }\r\n.site-nav__mark b { position: absolute; top: 50%; left: 50%; color: #fff; font-size: .44rem; font-weight: 600; letter-spacing: .1em; line-height: 1; text-shadow: 0 1px 3px rgba(0,0,0,.72); transform: translate(-50%,-50%); }\r\n.site-nav nav { display: grid; margin-top: clamp(4rem,15vh,8rem); }\r\n.site-nav__item { display: grid; grid-template-columns: 2rem 1fr; padding: 1rem .5rem; border: 0; border-top: 1px solid var(--hairline); background: transparent; text-align: left; cursor: pointer; font-size: .68rem; letter-spacing: .08em; }\r\n.site-nav__item:last-child { border-bottom: 1px solid var(--hairline); }\r\n.site-nav__item span { color: var(--ink-soft); font-size: .55rem; }\r\n.site-nav__item:hover, .site-nav__item.is-active { color: var(--paper); background: var(--ink); }\r\n.site-nav__item:hover span, .site-nav__item.is-active span { color: rgba(233,231,223,.62); }\r\n.site-nav__status { margin: auto 0 0; font-size: .55rem; letter-spacing: .08em; }\r\n.site-nav__status i { display: inline-block; width: 6px; height: 6px; margin-right: .5rem; border-radius: 50%; background: #3f764f; box-shadow: 0 0 0 4px rgba(63,118,79,.13); }\r\n.sheet { padding-left: 230px; }\r\n\r\n@media (max-width: 820px) {\r\n  .site-nav { inset: 0 0 auto 0; width: auto; height: 62px; padding: 0 1rem; flex-direction: row; align-items: center; }\r\n  .site-nav__identity span:not(.site-nav__mark), .site-nav__status, .site-nav__item span { display: none; }\r\n  .site-nav__mark { width: 36px; height: 36px; }\r\n  .site-nav nav { display: flex; margin: 0 0 0 auto; }\r\n  .site-nav__item { display: block; padding: 1.45rem .65rem; border: 0; font-size: .56rem; }\r\n  .site-nav__item:last-child { border-bottom: 0; }\r\n  .sheet { padding-top: 62px; padding-left: 0; }\r\n}\r\n\r\n.paper-grain {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 10;\r\n  pointer-events: none;\r\n  opacity: 0.2;\r\n  background-image:\r\n    repeating-radial-gradient(circle at 17% 29%, transparent 0 1px, rgba(0, 0, 0, 0.15) 1px 1.35px, transparent 1.35px 4px),\r\n    repeating-linear-gradient(93deg, transparent 0 3px, rgba(255, 255, 255, 0.16) 3px 4px);\r\n  background-size: 7px 7px, 11px 11px;\r\n  mix-blend-mode: multiply;\r\n}\r\n\r\n.sheet {\r\n  position: relative;\r\n  display: grid;\r\n  min-height: 100svh;\r\n  place-items: center;\r\n  overflow: hidden;\r\n  background:\r\n    linear-gradient(rgba(255, 255, 255, 0.12), rgba(0, 0, 0, 0.018)),\r\n    var(--paper);\r\n}\r\n\r\n.sheet::before {\r\n  position: absolute;\r\n  inset: 0;\r\n  content: '';\r\n  pointer-events: none;\r\n  background:\r\n    linear-gradient(to right, transparent 49.95%, rgba(17, 18, 16, 0.04) 50%, transparent 50.05%),\r\n    linear-gradient(to bottom, transparent 49.95%, rgba(17, 18, 16, 0.035) 50%, transparent 50.05%);\r\n}\r\n\r\n.bulletin {\r\n  width: min(88vw, 1480px);\r\n  margin: clamp(5rem, 8vh, 8rem) auto;\r\n}\r\n\r\n.eyebrow,\r\n.masthead h1,\r\n.metadata p,\r\n.target-kicker,\r\n.unit-label,\r\n.target-line,\r\n.footer-line,\r\n.side-note,\r\n.email-form label {\r\n  letter-spacing: 0.04em;\r\n}\r\n\r\n.eyebrow {\r\n  margin: 0 0 0.55rem;\r\n  color: var(--ink-soft);\r\n  font-size: clamp(0.62rem, 0.65vw, 0.78rem);\r\n}\r\n\r\n.masthead {\r\n  display: block;\r\n}\r\n\r\n.masthead h1 {\r\n  margin: 0;\r\n  font-size: clamp(1rem, 1.55vw, 1.75rem);\r\n  font-weight: 500;\r\n}\r\n\r\n.rule {\r\n  height: 1px;\r\n  margin: 1.9rem 0 0;\r\n  background: var(--line);\r\n}\r\n\r\n.rule--heavy {\r\n  height: 1.5px;\r\n  background: var(--ink);\r\n}\r\n\r\n.metadata {\r\n  display: grid;\r\n  grid-template-columns: repeat(4, 1fr);\r\n  border-bottom: 1px solid var(--line);\r\n}\r\n\r\n.metadata p {\r\n  margin: 0;\r\n  padding: 1rem 0;\r\n  font-size: clamp(0.62rem, 0.7vw, 0.78rem);\r\n}\r\n\r\n.metadata p:nth-child(even) {\r\n  text-align: right;\r\n}\r\n\r\n.metadata p:nth-child(3) {\r\n  padding-left: 1rem;\r\n}\r\n\r\n.metadata strong {\r\n  font-weight: 500;\r\n}\r\n\r\n.countdown-panel {\r\n  position: relative;\r\n  min-height: min(59vh, 650px);\r\n  padding: clamp(2.4rem, 6vh, 5.5rem) clamp(1rem, 3vw, 3rem) clamp(1.4rem, 3vh, 2.4rem);\r\n  border-right: 1px solid var(--line);\r\n  border-bottom: 1px solid var(--line);\r\n  border-left: 1px solid var(--line);\r\n  overflow: hidden;\r\n  background:\r\n    linear-gradient(rgba(233, 231, 223, 0.88), rgba(233, 231, 223, 0.88)),\r\n    repeating-linear-gradient(0deg, transparent 0 49px, rgba(17, 18, 16, 0.07) 49px 50px);\r\n}\r\n\r\n.countdown-panel::before,\r\n.countdown-panel::after {\r\n  position: absolute;\r\n  top: 0;\r\n  bottom: 0;\r\n  width: 1px;\r\n  content: '';\r\n  background: linear-gradient(transparent, var(--hairline) 20%, var(--hairline) 80%, transparent);\r\n}\r\n\r\n.countdown-panel::before {\r\n  left: 33.3333%;\r\n}\r\n\r\n.countdown-panel::after {\r\n  right: 33.3333%;\r\n}\r\n\r\n.target-kicker {\r\n  position: relative;\r\n  z-index: 1;\r\n  margin: 0;\r\n  text-align: center;\r\n  font-size: 0.65rem;\r\n}\r\n\r\n.timer {\r\n  position: relative;\r\n  z-index: 1;\r\n  display: grid;\r\n  grid-template-columns: repeat(3, minmax(0, 1fr));\r\n  align-items: start;\r\n  width: 100%;\r\n  margin-top: clamp(4rem, 12vh, 8rem);\r\n}\r\n\r\n.time-unit {\r\n  position: relative;\r\n  min-width: 0;\r\n  text-align: center;\r\n}\r\n\r\n.time-unit:not(:last-child)::after {\r\n  position: absolute;\r\n  top: -0.08em;\r\n  left: 100%;\r\n  z-index: 2;\r\n  content: ':';\r\n  font-family: var(--sans);\r\n  font-size: clamp(3.5rem, 7vw, 7.8rem);\r\n  font-weight: 300;\r\n  line-height: 0.78;\r\n  transform: translateX(-50%);\r\n}\r\n\r\n.time-value {\r\n  display: block;\r\n  font-family: var(--sans);\r\n  font-size: clamp(4.4rem, 10vw, 10.8rem);\r\n  font-weight: 300;\r\n  font-variant-numeric: tabular-nums lining-nums;\r\n  letter-spacing: -0.075em;\r\n  line-height: 0.78;\r\n  text-indent: -0.075em;\r\n  transition: opacity 120ms ease, filter 120ms ease, transform 120ms ease;\r\n}\r\n\r\n.time-value.is-ticking {\r\n  opacity: 0.58;\r\n  filter: blur(1.5px);\r\n  transform: translateY(0.045em);\r\n}\r\n\r\n.unit-label {\r\n  display: block;\r\n  margin-top: clamp(1.25rem, 3vh, 2.1rem);\r\n  font-size: clamp(0.55rem, 0.65vw, 0.75rem);\r\n}\r\n\r\n.target-line {\r\n  position: absolute;\r\n  right: clamp(1rem, 3vw, 3rem);\r\n  bottom: clamp(1rem, 2.4vh, 1.8rem);\r\n  left: clamp(1rem, 3vw, 3rem);\r\n  display: flex;\r\n  justify-content: space-between;\r\n  gap: 2rem;\r\n  padding-top: 0.8rem;\r\n  border-top: 1px solid var(--hairline);\r\n  font-size: clamp(0.55rem, 0.65vw, 0.72rem);\r\n}\r\n\r\n.target-line__label {\r\n  color: var(--ink-soft);\r\n}\r\n\r\n.target-line__value {\r\n  text-align: right;\r\n}\r\n\r\n.footer-line {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  gap: 2rem;\r\n  padding-top: 1.1rem;\r\n  font-size: clamp(0.56rem, 0.65vw, 0.72rem);\r\n}\r\n\r\n.footer-line p {\n  margin: 0;\n}\n\n.bulletin-alert {\n  display: grid;\n  margin-top: 1.1rem;\n  padding: clamp(1rem, 2.2vw, 1.5rem);\n  gap: 0.6rem;\n  border: 2px solid #9f1711;\n  color: #87130e;\n  background:\n    repeating-linear-gradient(135deg, rgba(159, 23, 17, 0.055) 0 2px, transparent 2px 9px),\n    rgba(255, 245, 241, 0.64);\n  text-decoration: none;\n  box-shadow: 7px 7px 0 rgba(135, 19, 14, 0.14);\n}\n\n.bulletin-alert:hover,\n.bulletin-alert:focus-visible {\n  color: #fff7f3;\n  background: #9f1711;\n  outline: 2px solid #9f1711;\n  outline-offset: 3px;\n}\n\n.bulletin-alert__status {\n  font-size: clamp(0.68rem, 0.8vw, 0.82rem);\n  font-weight: 700;\n  letter-spacing: 0.18em;\n}\n\n.bulletin-alert__message {\n  font-family: var(--sans);\n  font-size: clamp(1rem, 1.9vw, 1.5rem);\n  font-weight: 500;\n  letter-spacing: -0.02em;\n  line-height: 1.15;\n}\n\n.bulletin-alert__action {\n  font-size: clamp(0.65rem, 0.78vw, 0.78rem);\n  letter-spacing: 0.07em;\n  line-height: 1.55;\n}\n\n.bulletin-alert__action b {\n  white-space: nowrap;\n}\n\r\n.side-note {\r\n  position: absolute;\r\n  top: 50%;\r\n  left: 2.2vw;\r\n  margin: 0;\r\n  color: var(--ink-soft);\r\n  font-size: 0.58rem;\r\n  transform: translateY(-50%) rotate(-90deg);\r\n  transform-origin: center;\r\n}\r\n\r\n.registration {\r\n  position: absolute;\r\n  width: 34px;\r\n  height: 34px;\r\n  opacity: 0.55;\r\n}\r\n\r\n.registration::before,\r\n.registration::after {\r\n  position: absolute;\r\n  content: '';\r\n  background: var(--ink);\r\n}\r\n\r\n.registration::before {\r\n  top: 16px;\r\n  left: 0;\r\n  width: 34px;\r\n  height: 1px;\r\n}\r\n\r\n.registration::after {\r\n  top: 0;\r\n  left: 16px;\r\n  width: 1px;\r\n  height: 34px;\r\n}\r\n\r\n.registration--tl { top: 4vh; left: 3vw; }\r\n.registration--tc { top: 4vh; left: 50%; transform: translateX(-50%); }\r\n.registration--tr { top: 4vh; right: 3vw; }\r\n.registration--bl { bottom: 4vh; left: 3vw; }\r\n.registration--bc { bottom: 4vh; left: 50%; transform: translateX(-50%); }\r\n.registration--br { right: 3vw; bottom: 4vh; }\r\n\r\n.registration--tc::before,\r\n.registration--bc::before {\r\n  box-shadow: 0 0 0 6px var(--paper), 0 0 0 7px var(--ink);\r\n}\r\n\r\n.email-form {\r\n  min-width: 0;\r\n}\r\n\r\n.email-form label {\r\n  display: block;\r\n  margin-bottom: 0.55rem;\r\n  font-size: 0.62rem;\r\n}\r\n\r\n.email-form__entry {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr) auto;\r\n  gap: 0.8rem;\r\n  align-items: stretch;\r\n}\r\n\r\n.email-address {\r\n  display: flex;\r\n  min-width: 0;\r\n  min-height: 46px;\r\n  align-items: center;\r\n  border: 1px solid var(--ink);\r\n  background: rgba(255, 255, 255, 0.14);\r\n  transition: box-shadow 150ms ease;\r\n}\r\n\r\n.email-address:focus-within {\r\n  box-shadow: 0 0 0 2px var(--paper), 0 0 0 4px var(--ink);\r\n}\r\n\r\n.email-address input {\r\n  min-width: 0;\r\n  flex: 1 1 auto;\r\n  padding: 0.78rem 0.35rem 0.78rem 0.8rem;\r\n  border: 0;\r\n  outline: 0;\r\n  color: var(--ink);\r\n  background: transparent;\r\n  font-size: 0.9rem;\r\n}\r\n\r\n.email-address input::placeholder {\r\n  color: rgba(17, 18, 16, 0.32);\r\n}\r\n\r\n.email-address input[aria-invalid='true'] {\r\n  text-decoration: underline wavy currentColor;\r\n  text-underline-offset: 0.22em;\r\n}\r\n\r\n.email-domain {\r\n  flex: 0 0 auto;\r\n  padding-right: 0.8rem;\r\n  color: var(--ink-soft);\r\n  font-size: clamp(0.68rem, 0.78vw, 0.85rem);\r\n  white-space: nowrap;\r\n}\r\n\r\n.submit-button {\r\n  min-width: 104px;\r\n  padding: 0.75rem 1rem;\r\n  border: 1px solid var(--ink);\r\n  border-radius: 0;\r\n  color: var(--paper-bright);\r\n  background: var(--ink);\r\n  cursor: pointer;\r\n  font-size: 0.65rem;\r\n  letter-spacing: 0.08em;\r\n  transition: color 150ms ease, background 150ms ease;\r\n}\r\n\r\n.submit-button:hover:not(:disabled),\r\n.submit-button:focus-visible {\r\n  color: var(--ink);\r\n  background: var(--paper-bright);\r\n  outline: 2px solid var(--ink);\r\n  outline-offset: 2px;\r\n}\r\n\r\n.submit-button:disabled {\r\n  cursor: wait;\r\n  opacity: 0.58;\r\n}\r\n\r\n.email-form__hint,\r\n.email-form__status {\r\n  margin: 0.5rem 0 0;\r\n  font-size: 0.58rem;\r\n  line-height: 1.45;\r\n}\r\n\r\n.email-form__hint {\r\n  color: var(--ink-soft);\r\n}\r\n\r\n.email-form__status {\r\n  min-height: 0.85rem;\r\n}\r\n\r\n.email-form__status.is-error {\r\n  color: #8b1e16;\r\n}\r\n\r\n.email-form__status.is-success {\r\n  color: #245f3d;\r\n}\r\n\r\n/* ================================================================\r\n   FIRST CONTACT TRANSMISSION\r\n   ================================================================ */\r\n.signal {\r\n  width: min(92vw, 560px);\r\n  padding: 0;\r\n  border: 0;\r\n  color: var(--ink);\r\n  background: transparent;\r\n}\r\n\r\n.signal::backdrop {\r\n  background: rgba(17, 18, 16, 0.6);\r\n  backdrop-filter: blur(2px);\r\n}\r\n\r\n.signal[open] {\r\n  animation: signal-in 260ms cubic-bezier(0.2, 0.7, 0.3, 1);\r\n}\r\n\r\n@keyframes signal-in {\r\n  from {\r\n    opacity: 0;\r\n    transform: translateY(-10px);\r\n  }\r\n}\r\n\r\n.signal__card {\r\n  position: relative;\r\n  padding: clamp(1.1rem, 3vw, 1.9rem);\r\n  border: 1.5px solid var(--ink);\r\n  background:\r\n    linear-gradient(rgba(233, 231, 223, 0.94), rgba(233, 231, 223, 0.94)),\r\n    repeating-linear-gradient(0deg, transparent 0 49px, rgba(17, 18, 16, 0.07) 49px 50px),\r\n    var(--paper);\r\n  box-shadow: 12px 12px 0 rgba(17, 18, 16, 0.2);\r\n}\r\n\r\n.signal__head {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  justify-content: space-between;\r\n  gap: 1.5rem;\r\n}\r\n\r\n.signal__head .eyebrow {\r\n  margin: 0;\r\n}\r\n\r\n/* One control holds both states: the breathing dots while the transmission is\r\n   live, then the close cross once the other side drops. */\r\n.signal__dismiss {\r\n  position: relative;\r\n  display: grid;\r\n  width: 40px;\r\n  height: 40px;\r\n  flex: 0 0 auto;\r\n  place-items: center;\r\n  border: 1px solid var(--ink);\r\n  color: var(--ink);\r\n  background: transparent;\r\n  cursor: default;\r\n}\r\n\r\n.signal__dismiss:disabled {\r\n  opacity: 1;\r\n}\r\n\r\n.signal__dots {\r\n  display: flex;\r\n  gap: 4px;\r\n}\r\n\r\n.signal__dots i {\r\n  width: 4px;\r\n  height: 4px;\r\n  border-radius: 50%;\r\n  background: var(--ink);\r\n  animation: signal-dot 1.3s ease-in-out infinite;\r\n}\r\n\r\n.signal__dots i:nth-child(2) { animation-delay: 0.16s; }\r\n.signal__dots i:nth-child(3) { animation-delay: 0.32s; }\r\n\r\n@keyframes signal-dot {\r\n  0%, 100% { opacity: 0.22; transform: translateY(1px); }\r\n  50% { opacity: 1; transform: translateY(-2px); }\r\n}\r\n\r\n.signal.is-severing .signal__dots i {\r\n  animation-duration: 0.3s;\r\n}\r\n\r\n.signal__close {\n  display: none;\n  font-family: var(--sans);\n  font-size: 1.75rem;\n  font-weight: 700;\n  line-height: 1;\n}\n\n.signal.is-closable .signal__dots { display: none; }\n.signal.is-closable .signal__close { display: block; }\n.signal.is-closable .signal__dismiss {\n  border-color: #a90f09;\n  color: #a90f09;\n  background: #fff2ee;\n  cursor: pointer;\n  box-shadow: 0 0 0 4px rgba(169, 15, 9, 0.13);\n  animation: signal-close-ready 850ms ease-out 2;\n}\n\n@keyframes signal-close-ready {\n  50% { box-shadow: 0 0 0 8px rgba(169, 15, 9, 0); }\n}\n\n.signal.is-closable .signal__dismiss:hover,\n.signal.is-closable .signal__dismiss:focus-visible {\n  color: #fff;\n  background: #a90f09;\n  outline: 0;\n}\n\r\n.signal .rule--heavy {\r\n  margin-top: 0.9rem;\r\n}\r\n\r\n.signal__body {\n  min-height: clamp(180px, 32vh, 300px);\n  max-height: 52vh;\r\n  padding-top: 1.4rem;\r\n  overflow-y: auto;\r\n}\n\n.signal:not(.is-receiving) .signal__body {\n  display: grid;\n  min-height: clamp(105px, 19vh, 145px);\n  padding: 0.75rem 0;\n  place-items: center;\n  text-align: center;\n}\n\r\n.signal__question {\r\n  margin: 0;\r\n  font-family: var(--sans);\r\n  font-size: clamp(1.5rem, 5vw, 2.4rem);\r\n  font-weight: 300;\r\n  letter-spacing: -0.03em;\r\n  line-height: 1.06;\r\n}\r\n\r\n.signal__line {\r\n  margin: 0 0 0.8rem;\r\n  font-size: clamp(0.72rem, 1.5vw, 0.86rem);\r\n  letter-spacing: 0.13em;\r\n  animation: signal-line-in 300ms ease-out;\r\n}\r\n\r\n@keyframes signal-line-in {\r\n  from {\r\n    opacity: 0;\r\n    filter: blur(3px);\r\n    transform: translateY(4px);\r\n  }\r\n}\r\n\r\n.signal__actions {\n  display: flex;\n  justify-content: flex-end;\r\n  padding-top: 1.1rem;\r\n  border-top: 1px solid var(--hairline);\n}\n\n.signal:not(.is-receiving) .signal__actions {\n  justify-content: center;\n  padding-top: 0.85rem;\n}\n\r\n.signal__yes {\r\n  min-width: 124px;\r\n  padding: 0.85rem 1.6rem;\r\n  border: 1px solid var(--ink);\r\n  color: var(--paper-bright);\r\n  background: var(--ink);\r\n  cursor: pointer;\r\n  font-size: 0.68rem;\r\n  letter-spacing: 0.2em;\r\n  transition: color 150ms ease, background 150ms ease;\r\n}\r\n\r\n.signal__yes:hover,\r\n.signal__yes:focus-visible {\r\n  color: var(--ink);\r\n  background: transparent;\r\n  outline: 0;\r\n}\r\n\r\n.is-expired .countdown-panel {\r\n  animation: terminal-pulse 2s steps(2, end) infinite;\r\n}\r\n\r\n@keyframes terminal-pulse {\r\n  50% { background-color: rgba(17, 18, 16, 0.05); }\r\n}\r\n\r\n@media (max-width: 820px) {\r\n  .bulletin {\r\n    width: min(86vw, 650px);\r\n    margin: 6.5rem auto;\r\n  }\r\n\r\n  .masthead {\r\n    align-items: flex-start;\r\n  }\r\n\r\n  .masthead h1 {\r\n    max-width: 16rem;\r\n  }\r\n\r\n  .metadata {\r\n    grid-template-columns: 1fr 1fr;\r\n  }\r\n\r\n  .metadata p:nth-child(n + 3) {\r\n    border-top: 1px solid var(--hairline);\r\n  }\r\n\r\n  .countdown-panel {\r\n    min-height: 56svh;\r\n    padding-top: 3rem;\r\n  }\r\n\r\n  .timer {\r\n    grid-template-columns: repeat(3, minmax(0, 1fr));\r\n    gap: 0;\r\n  }\r\n\r\n  .time-unit:not(:last-child)::after {\r\n    font-size: clamp(2.5rem, 9vw, 4.5rem);\r\n  }\r\n\r\n  .time-value {\r\n    font-size: clamp(3.5rem, 16vw, 7rem);\r\n  }\r\n\r\n  .target-line {\r\n    display: grid;\r\n    gap: 0.35rem;\r\n  }\r\n\r\n  .target-line__value {\r\n    text-align: left;\r\n  }\r\n\r\n  .side-note,\r\n  .registration--tc,\r\n  .registration--bc {\r\n    display: none;\r\n  }\r\n}\r\n\r\n@media (max-width: 520px) {\r\n  .sheet {\r\n    min-height: 100dvh;\r\n    place-items: start center;\r\n    overflow-y: auto;\r\n  }\r\n\r\n  .bulletin {\r\n    width: 92vw;\r\n    margin: 3.25rem auto 2rem;\r\n  }\r\n\r\n  .masthead h1 {\r\n    max-width: none;\r\n    font-size: 0.88rem;\r\n  }\r\n\r\n  .eyebrow {\r\n    margin-bottom: 0.35rem;\r\n    font-size: 0.52rem;\r\n  }\r\n\r\n  .rule {\r\n    margin-top: 1rem;\r\n  }\r\n\r\n  .metadata p {\r\n    padding: 0.65rem 0;\r\n    overflow: hidden;\r\n    font-size: 0.56rem;\r\n    text-overflow: ellipsis;\r\n    white-space: nowrap;\r\n  }\r\n\r\n  .countdown-panel {\r\n    min-height: min(58svh, 470px);\r\n    padding: 2rem 0.55rem 1.25rem;\r\n  }\r\n\r\n  .target-kicker {\r\n    font-size: 0.56rem;\r\n  }\r\n\r\n  .timer {\r\n    margin-top: clamp(4.5rem, 14svh, 7rem);\r\n  }\r\n\r\n  .timer {\r\n    grid-template-columns: repeat(3, minmax(0, 1fr));\r\n    gap: 0;\r\n  }\r\n\r\n  .time-value {\r\n    font-size: clamp(3rem, 14vw, 4.7rem);\r\n  }\r\n\r\n  .time-unit--hours .time-value {\r\n    font-size: clamp(2.7rem, 12.5vw, 4.3rem);\r\n    letter-spacing: -0.1em;\r\n  }\r\n\r\n  .time-unit:not(:last-child)::after {\r\n    top: 0;\r\n    font-size: clamp(2rem, 8vw, 3.2rem);\r\n  }\r\n\r\n  .unit-label {\r\n    margin-top: 1rem;\r\n    font-size: 0.5rem;\r\n  }\r\n\r\n  .target-line {\r\n    right: 0.75rem;\r\n    bottom: 0.75rem;\r\n    left: 0.75rem;\r\n    display: flex;\r\n    gap: 0.75rem;\r\n    font-size: 0.5rem;\r\n  }\r\n\r\n  .target-line__value {\r\n    margin-left: auto;\r\n    text-align: right;\r\n  }\r\n\r\n  .footer-line {\r\n    padding-top: 0.75rem;\r\n    font-size: 0.5rem;\r\n  }\r\n\r\n  .footer-line p:last-child {\r\n    display: none;\r\n  }\r\n\r\n  .registration {\r\n    width: 24px;\r\n    height: 24px;\r\n  }\r\n\r\n  .registration::before {\r\n    top: 11px;\r\n    width: 24px;\r\n  }\r\n\r\n  .registration::after {\r\n    left: 11px;\r\n    height: 24px;\r\n  }\r\n\r\n  .registration--tl,\r\n  .registration--tr {\r\n    top: 1.25rem;\r\n  }\r\n\r\n  .registration--bl,\r\n  .registration--br {\r\n    display: none;\r\n  }\r\n\r\n  .email-form__entry {\r\n    grid-template-columns: 1fr;\r\n    gap: 0.65rem;\r\n  }\r\n\r\n  .email-address {\r\n    min-height: 48px;\r\n  }\r\n\r\n  .email-address input {\r\n    padding-left: 0.65rem;\r\n    font-size: 0.82rem;\r\n  }\r\n\r\n  .email-domain {\r\n    padding-right: 0.65rem;\r\n    font-size: 0.62rem;\r\n  }\r\n\r\n  .submit-button {\r\n    min-height: 46px;\r\n    width: 100%;\r\n  }\r\n\r\n  .signal {\r\n    width: 92vw;\r\n  }\r\n\r\n  .signal__card {\r\n    padding: 1.1rem 0.95rem 1.2rem;\r\n    box-shadow: 7px 7px 0 rgba(17, 18, 16, 0.2);\r\n  }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n  *,\r\n  *::before,\r\n  *::after {\r\n    scroll-behavior: auto !important;\r\n    animation-duration: 0.01ms !important;\r\n    animation-iteration-count: 1 !important;\r\n    transition-duration: 0.01ms !important;\r\n  }\r\n}\r\n\r\n/* Multi-view observation console */\r\n.app-main { display: block; min-height: 100svh; }\r\n.view { display: none; }\r\n.view.is-active { display: block; animation: view-in 360ms cubic-bezier(.2,.75,.25,1); }\r\n.bulletin.view.is-active { margin-top: 0; padding-top: clamp(5rem,8vh,8rem); padding-bottom: clamp(5rem,8vh,8rem); }\r\n@keyframes view-in { from { opacity: 0; transform: translateY(8px); filter: blur(3px); } }\r\n.console-view { width: 100%; min-width: 0; min-height: 100svh; margin: 0; padding: clamp(5rem,8vh,7rem) clamp(1.5rem,4vw,5rem) 4rem; }\r\n.view-head { position: relative; }\r\n.view-head h1 { margin: 0; font-family: var(--sans); font-size: clamp(2rem,5vw,5.4rem); font-weight: 300; letter-spacing: -.055em; line-height: .9; }\r\n.view-code { position: absolute; right: 0; bottom: .15rem; margin: 0; color: var(--ink-soft); font-size: .58rem; letter-spacing: .08em; }\r\n.console-view > .rule { margin: 2rem 0 0; }\r\n\r\n.archive-list { padding-top: clamp(3rem,8vh,7rem); }\r\n.archive-link { display: grid; grid-template-columns: minmax(0,1fr) minmax(130px,.45fr) 7.5rem; gap: 1.5rem; align-items: center; padding: 1.45rem .5rem; border-top: 1px solid var(--line); color: var(--ink); text-decoration: none; transition: padding 180ms,background 180ms,color 180ms; }\r\n.archive-link:last-child { border-bottom: 1px solid var(--line); }\r\n.archive-link:hover,.archive-link:focus-visible { padding-right: 1rem; padding-left: 1rem; color: var(--paper); background: var(--ink); outline: 0; }\r\n.archive-link strong { font-family: var(--sans); font-size: clamp(1rem,1.8vw,1.55rem); font-weight: 300; letter-spacing: -.015em; }\r\n.archive-link time,.archive-link span { font-size: .62rem; font-weight: 400; letter-spacing: .08em; }\r\n.archive-link span { justify-self: end; }\r\n.archive-link.is-restricted span { color: #7d302a; }\r\n.archive-link.is-restricted:hover span,.archive-link.is-restricted:focus-visible span { color: #ffb7b0; }\r\n\r\n.packet-viewer,.restricted-dialog { width: min(1100px,calc(100vw - 3rem)); max-width: none; margin: auto; padding: 0; border: 1px solid var(--ink); color: var(--ink); background: var(--paper); box-shadow: 18px 18px 0 rgba(17,18,16,.18); }\r\n.packet-viewer::backdrop,.restricted-dialog::backdrop { background: rgba(17,18,16,.72); backdrop-filter: blur(3px); }\r\n.packet-viewer__card { max-height: calc(100vh - 3rem); overflow: auto; }\r\n.packet-dialog__head { position: sticky; z-index: 2; top: 0; display: flex; align-items: flex-start; justify-content: space-between; gap: 2rem; padding: 1rem 1.25rem; border-bottom: 1px solid var(--ink); background: var(--paper); }\r\n.packet-dialog__head .eyebrow { margin: 0 0 .35rem; }\r\n.packet-dialog__head h2 { margin: 0; font-family: var(--sans); font-size: clamp(1.2rem,2.3vw,2rem); font-weight: 300; letter-spacing: -.035em; }\r\n.packet-dialog__close { width: 40px; height: 40px; flex: 0 0 auto; border: 1px solid var(--ink); color: var(--ink); background: transparent; cursor: pointer; font-size: 1rem; }\r\n.packet-dialog__close:hover,.packet-dialog__close:focus-visible { color: var(--paper); background: var(--ink); outline: 0; }\r\n.packet-viewer__pages { display: grid; gap: 1.5rem; padding: 1.25rem clamp(.5rem,2vw,1.5rem) clamp(1.25rem,3vw,2rem); }\r\n.packet-page { margin: 0; }\r\n.packet-page img { display: block; width: min(100%,860px); height: auto; margin: 0 auto; background: #fff; }\r\n.packet-page figcaption { margin: .7rem auto 0; width: min(100%,860px); color: var(--ink-soft); font-size: .52rem; letter-spacing: .12em; }\r\n\r\n.archive-note { margin: 1.6rem 0 0; color: var(--ink-soft); font-size: .56rem; letter-spacing: .12em; }\r\n.archive-note[data-state=\"withheld\"] { color: #7d302a; }\r\n.archive-note[data-state=\"granted\"] { color: #2f5c42; }\r\n\r\n/* Recovered 2008 conversation sheets, rebuilt from the archive scan. */\r\n.recovered { --recovered-red: #b30000; width: min(100%,880px); margin: 0 auto; border: 2px solid #111; background: #000; color: var(--recovered-red); font-size: clamp(.62rem,1.5vw,.8rem); }\r\n.recovered__head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; padding: .85rem clamp(.8rem,2.5vw,1.5rem); background: #295cdb; color: #fff; }\r\n.recovered__head b { font-size: clamp(.78rem,2vw,1.1rem); letter-spacing: .06em; }\r\n.recovered__head span { font-size: clamp(.55rem,1.3vw,.78rem); font-weight: 400; }\r\n.recovered__body { padding: clamp(.9rem,2.5vw,1.5rem); }\r\n.recovered__tags { display: flex; justify-content: space-between; gap: 1rem; font-size: clamp(.55rem,1.3vw,.72rem); font-weight: 700; letter-spacing: .08em; }\r\n.recovered__meta { display: flex; flex-wrap: wrap; gap: clamp(1.2rem,5vw,3.4rem); margin: 1.3rem 0 0; padding-bottom: 1.1rem; border-bottom: 1px solid #fff; }\r\n.recovered__meta div { margin: 0; }\r\n.recovered__meta dt { font-size: clamp(.52rem,1.2vw,.7rem); opacity: .8; }\r\n.recovered__meta dd { margin: .35rem 0 0; font-size: clamp(.62rem,1.5vw,.85rem); }\r\n.recovered__grid { display: grid; grid-template-columns: minmax(0,1fr) clamp(150px,24%,230px); gap: clamp(1rem,3vw,2.5rem); align-items: start; padding: clamp(1.4rem,4vw,2.6rem) 0; }\r\n.recovered__label { margin: 0 0 1.2rem; font-size: clamp(.55rem,1.3vw,.75rem); font-weight: 700; letter-spacing: .08em; }\r\n/* The scan spaces some words apart mid-line; pre-wrap keeps that spacing. */\r\n.recovered__line { margin: 0 0 .55rem; padding-left: clamp(.5rem,2vw,1.6rem); font-family: var(--sans); font-size: clamp(.95rem,2.5vw,1.5rem); font-weight: 700; line-height: 1.25; white-space: pre-wrap; }\r\n.recovered__glass { display: grid; margin: 0; padding: clamp(.8rem,2vw,1.4rem); gap: .6rem; justify-items: center; border: 1.5px dashed #fff; }\r\n.recovered__glass figcaption { font-family: var(--sans); font-size: clamp(1.6rem,4.5vw,2.9rem); }\r\n.recovered-symbol { width: 100%; max-width: 150px; height: auto; fill: none; stroke: var(--recovered-red); stroke-width: 3; stroke-linejoin: round; }\r\n.recovered__foot { display: flex; justify-content: space-between; gap: 1rem; padding-top: 1rem; border-top: 1px solid #fff; font-size: clamp(.52rem,1.2vw,.72rem); }\r\n\r\n.packet-record-stack { position: relative; width: min(100%,880px); margin: 0 auto; }\n.packet-record-stack .recovered { width: 100%; }\n.related-record { position: absolute; right: clamp(.7rem,3vw,2rem); bottom: clamp(.8rem,3vw,2rem); left: clamp(.7rem,3vw,2rem); z-index: 1; padding: clamp(1rem,3vw,1.7rem); border: 2px solid #a90f09; background: rgba(241,239,232,.96); box-shadow: 9px 9px 0 rgba(0,0,0,.28); }\n.related-record__label { margin: 0 0 .65rem; color: #a90f09; font-size: clamp(.62rem,1.4vw,.78rem); font-weight: 700; letter-spacing: .2em; }\n.related-record__link { display: inline-block; color: var(--ink); font-family: var(--sans); font-size: clamp(1.35rem,4.5vw,2.8rem); font-weight: 500; letter-spacing: -.035em; line-height: 1.05; text-decoration: none; border-bottom: 2px solid var(--ink); word-break: break-all; }\n.related-record__link:hover,.related-record__link:focus-visible { color: var(--paper); background: var(--ink); outline: 3px solid var(--ink); outline-offset: 2px; }\n.related-record__note { margin: .8rem 0 0; color: var(--ink-soft); font-size: clamp(.52rem,1.2vw,.66rem); letter-spacing: .1em; }\n\r\n.restricted-dialog { width: min(620px,calc(100vw - 3rem)); }\r\n.restricted-dialog__card { padding: clamp(1.5rem,4vw,3rem); }\r\n.restricted-dialog .packet-dialog__head { position: static; margin-bottom: clamp(3rem,8vh,6rem); padding: 0 0 .9rem; }\r\n.restricted-dialog h2 { margin: 0; font-family: var(--sans); font-size: clamp(1.45rem,4vw,3rem); font-weight: 300; letter-spacing: -.04em; }\r\n.restricted-dialog__packet { margin: 1rem 0 3rem; color: var(--ink-soft); font-size: .56rem; letter-spacing: .1em; }\r\n.archive-form { width: 100%; margin: 0; text-align: left; }\r\n.archive-form label { display: block; margin-bottom: .8rem; font-size: .58rem; letter-spacing: .11em; }\r\n.restricted-entry { display: grid; grid-template-columns: auto minmax(0,1fr) auto; gap: .7rem; align-items: center; }\r\n.restricted-entry::before { content: '['; }\r\n.restricted-entry::after { content: ']'; }\r\n.archive-form input { width: 100%; min-width: 0; padding: .65rem .1rem; border: 0; border-bottom: 1px solid var(--ink); outline: 0; color: var(--ink); background: transparent; font-size: 1rem; letter-spacing: .45em; text-transform: uppercase; }\r\n.archive-form input:focus { border-bottom-width: 2px; }\r\n.restricted-access { margin-top: 2rem; padding: .7rem 1rem; border: 0; color: var(--ink); background: transparent; cursor: pointer; font-size: .62rem; letter-spacing: .1em; }\r\n.restricted-access::before { content: '[ '; }\r\n.restricted-access::after { content: ' ]'; }\r\n.restricted-access:hover,.restricted-access:focus-visible { color: var(--paper); background: var(--ink); outline: 0; }\r\n#archive-status { min-height: 1rem; margin: 1rem 0 0; font-size: .58rem; letter-spacing: .08em; }\r\n#archive-status[data-state=\"error\"] { color: #8b1e16; }\r\n#archive-status[data-state=\"success\"] { color: #245f3d; }\r\n\r\n@keyframes status-pulse { 50% { box-shadow: 0 0 0 8px rgba(51,114,75,0); } }\r\n\r\n.terminal-window { margin-top: 2rem; border: 1px solid var(--ink); color: #d9f0dc; background: #101411; box-shadow: 14px 14px 0 rgba(17,18,16,.12); }\r\n.terminal-bar { display: flex; justify-content: space-between; padding: .8rem 1rem; border-bottom: 1px solid rgba(217,240,220,.24); color: rgba(217,240,220,.58); font-size: .55rem; letter-spacing: .08em; }\r\n.terminal-output { position: relative; min-height: 55vh; padding: clamp(1.5rem,4vw,3rem); overflow: hidden; background: radial-gradient(circle at 40% 50%,rgba(79,162,91,.07),transparent 45%),repeating-linear-gradient(0deg,transparent 0 3px,rgba(255,255,255,.02) 3px 4px); text-shadow: 0 0 9px rgba(122,255,142,.22); }\r\n.terminal-output::before { position: absolute; inset: 0; content: ''; pointer-events: none; background: linear-gradient(90deg,transparent,rgba(160,255,180,.03),transparent); animation: terminal-sweep 4s linear infinite; }\r\n@keyframes terminal-sweep { from { transform: translateX(-100%); } to { transform: translateX(100%); } }\r\n.terminal-output p { display: grid; grid-template-columns: 9rem 7rem 1fr; margin: 0; padding: .78rem 0; border-bottom: 1px solid rgba(217,240,220,.1); font-size: clamp(.6rem,1vw,.76rem); letter-spacing: .05em; }\r\n.terminal-output time { color: rgba(217,240,220,.52); }\r\n.terminal-output b { color: #74bc80; font-weight: 400; }\r\n.terminal-prompt { display: flex; gap: .6rem; margin-top: 2rem; align-items: center; font-size: .7rem; }\r\n.terminal-prompt i { width: 8px; height: 1em; background: #d9f0dc; animation: blink 1s steps(2,end) infinite; }\r\n@keyframes blink { 50% { opacity: 0; } }\r\n.terminal-window footer { display: flex; justify-content: space-between; gap: 1rem; padding: .8rem 1rem; border-top: 1px solid rgba(217,240,220,.24); color: rgba(217,240,220,.55); font-size: .5rem; }\r\n\r\n.about-view { --about-ink: #161b1c; --about-muted: #697274; position: relative; isolation: isolate; }\r\n.about-view::before { position: absolute; z-index: -1; inset: 0; content: ''; background: linear-gradient(105deg,#e8eceb 0%,#dde2e1 100%); }\r\n.about-view .eyebrow,.about-view .view-code { color: var(--about-muted); }\r\n.about-view > .rule { background: var(--about-ink); }\r\n.about-minimal { display: grid; min-height: clamp(500px,66vh,720px); grid-template-columns: minmax(120px,.32fr) minmax(0,1.68fr); color: var(--about-ink); border-bottom: 1px solid var(--about-ink); }\r\n.about-minimal__index { margin: 0; padding: 2rem 1rem 0 0; border-right: 1px solid rgba(22,27,28,.22); color: var(--about-muted); font-size: .54rem; letter-spacing: .12em; line-height: 1.7; }\r\n.about-minimal__index span { opacity: .64; font-size: .45rem; }\r\n.about-minimal__copy { display: flex; max-width: 900px; padding: clamp(4rem,10vh,8rem) clamp(2rem,6vw,7rem) clamp(4rem,8vh,7rem); flex-direction: column; justify-content: space-between; }\r\n.about-minimal__copy p { margin: 0; }\r\n.about-minimal__copy p:first-child { font-family: var(--sans); font-size: clamp(1.7rem,3vw,3.6rem); font-weight: 300; letter-spacing: -.04em; line-height: 1.14; }\r\n.about-minimal__copy p:last-child { max-width: 34rem; margin-top: clamp(4rem,10vh,8rem); color: #3f484a; font-size: clamp(.65rem,.8vw,.82rem); letter-spacing: .05em; line-height: 1.75; }\r\n.about-minimal footer { grid-column: 1/-1; display: flex; justify-content: space-between; gap: 1rem; margin-top: auto; padding: .9rem 0; border-top: 1px solid rgba(22,27,28,.22); color: var(--about-muted); font-size: .48rem; letter-spacing: .1em; }\r\n.about-minimal footer i { display: inline-block; width: 5px; height: 5px; margin-right: .5rem; border-radius: 50%; background: #4c7871; }\r\n\r\n.affiliation { display: grid; grid-template-columns: minmax(120px,.32fr) minmax(0,1.68fr); color: var(--about-ink); border-bottom: 1px solid var(--about-ink); }\r\n.affiliation__index { margin: 0; padding: 2rem 1rem 0 0; border-right: 1px solid rgba(22,27,28,.22); color: var(--about-muted); font-size: .54rem; letter-spacing: .12em; line-height: 1.7; }\r\n.affiliation__index span { opacity: .64; font-size: .45rem; }\r\n.affiliation__panel { max-width: 900px; padding: clamp(2.5rem,7vh,5rem) clamp(2rem,6vw,7rem) clamp(2.5rem,7vh,5rem); }\r\n.affiliation h2 { margin: 0; font-size: clamp(.72rem,1.1vw,.95rem); font-weight: 700; letter-spacing: .18em; }\r\n.affiliation__deck { max-width: 34rem; margin: 1.1rem 0 2.4rem; color: #3f484a; font-size: clamp(.65rem,.8vw,.82rem); letter-spacing: .05em; line-height: 1.75; }\r\n.affiliation .email-form { max-width: 540px; }\r\n.affiliation__result { max-width: 540px; margin-top: 2.4rem; padding: 1.3rem 1.4rem 1.5rem; border: 1px solid var(--about-ink); background: rgba(255,255,255,.45); }\r\n.affiliation__confirm { margin: 0 0 1.2rem; color: #2f5c42; font-size: .6rem; letter-spacing: .18em; }\r\n.affiliation__fields { margin: 0; }\r\n.affiliation__fields div { padding: .85rem 0; border-top: 1px solid rgba(22,27,28,.2); }\r\n.affiliation__fields dt { color: var(--about-muted); font-size: .5rem; letter-spacing: .13em; }\r\n.affiliation__fields dd { margin: .4rem 0 0; font-family: var(--sans); font-size: clamp(1rem,2vw,1.4rem); font-weight: 400; letter-spacing: .06em; word-break: break-all; }\r\n.affiliation__hint { margin: 1.3rem 0 0; color: var(--about-muted); font-size: .55rem; letter-spacing: .09em; }\r\n\r\n@media (max-width: 900px) {\r\n  .about-minimal,.affiliation { grid-template-columns: 100px minmax(0,1fr); }\r\n}\r\n@media (max-width: 600px) {\r\n  .site-nav__item { padding-right: .42rem; padding-left: .42rem; font-size: .48rem; }\r\n  .console-view { width: 100%; padding: 7rem 1rem 2rem; }\r\n  .view-code { display: none; }\r\n  .archive-link { grid-template-columns: 1fr auto; gap: .7rem; }\r\n  .archive-link time { grid-row: 2; grid-column: 1; }\r\n  .archive-link span { grid-row: 1 / 3; grid-column: 2; }\r\n  .packet-viewer,.restricted-dialog { width: calc(100vw - 1rem); }\r\n  .packet-viewer__card { max-height: calc(100vh - 1rem); }\r\n  .restricted-dialog__card { padding: 1.25rem; }\r\n  .terminal-output p { grid-template-columns: 6.3rem 1fr; gap: .5rem; }\r\n  .terminal-output p span { grid-column: 2; }\r\n  .terminal-window footer span:nth-child(2) { display: none; }\r\n  .about-minimal { min-height: 70vh; grid-template-columns: 1fr; }\r\n  .about-minimal__index { padding: 1rem 0; border-right: 0; border-bottom: 1px solid rgba(22,27,28,.22); }\r\n  .about-minimal__copy { min-height: 54vh; padding: 3rem 1rem 3.5rem 0; }\r\n  .about-minimal__copy p:first-child { font-size: clamp(1.65rem,7.4vw,2.5rem); }\r\n  .about-minimal__copy p:last-child { margin-top: 4rem; }\r\n  .about-minimal footer { align-items: flex-start; flex-direction: column; }\r\n  .affiliation { grid-template-columns: 1fr; }\r\n  .affiliation__index { padding: 1rem 0; border-right: 0; border-bottom: 1px solid rgba(22,27,28,.22); }\r\n  .affiliation__panel { padding: 2.5rem 0 3rem; }\r\n  .recovered__grid { grid-template-columns: 1fr; }\r\n  .recovered__glass { justify-self: start; width: min(100%,220px); }\r\n  .packet-viewer__pages { gap: 1rem; padding: 1rem .5rem 1.25rem; }\r\n}\r\n\r\n/* ================================================================\r\n   EXPANDING OBSERVATION RAIL / NAVIGATION V2\r\n   ================================================================ */\r\n@media (min-width: 821px) {\r\n  .site-nav {\r\n    --rail-width: 76px;\r\n    --rail-open: 268px;\r\n    --nav-y: 50%;\r\n    width: var(--rail-width);\r\n    padding: 1rem 11px 1.1rem;\r\n    overflow: hidden;\r\n    border: 0;\r\n    border-right: 1px solid rgba(17,18,16,.24);\r\n    background:\r\n      radial-gradient(circle at 36px var(--nav-y), rgba(255,255,255,.95), transparent 120px),\r\n      rgba(225,223,214,.91);\r\n    box-shadow: 10px 0 34px rgba(17,18,16,.08);\r\n    backdrop-filter: blur(18px) saturate(.8);\r\n    transition: width 440ms cubic-bezier(.18,.78,.2,1), box-shadow 440ms ease, background 220ms ease;\r\n  }\r\n\r\n  .site-nav:hover,\r\n  .site-nav:focus-within,\r\n  .site-nav.is-peeking {\r\n    width: var(--rail-open);\r\n    box-shadow: 20px 0 60px rgba(17,18,16,.16), inset -1px 0 rgba(255,255,255,.7);\r\n  }\r\n\r\n  .site-nav::before {\r\n    position: absolute;\r\n    inset: 7px;\r\n    content: '';\r\n    pointer-events: none;\r\n    border: 1px solid rgba(17,18,16,.12);\r\n  }\r\n\r\n  .site-nav::after {\r\n    position: absolute;\r\n    top: 50%;\r\n    right: -1px;\r\n    width: 1px;\r\n    height: 70px;\r\n    content: '';\r\n    pointer-events: none;\r\n    background: var(--ink);\r\n    transform: translateY(-50%);\r\n    transition: height 440ms cubic-bezier(.18,.78,.2,1);\r\n  }\r\n\r\n  .site-nav:hover::after,\r\n  .site-nav:focus-within::after { height: 160px; }\r\n\r\n  .nav-scan {\r\n    position: absolute;\r\n    z-index: 0;\r\n    top: -40px;\r\n    right: 8px;\r\n    left: 8px;\r\n    height: 34px;\r\n    pointer-events: none;\r\n    opacity: .45;\r\n    background: linear-gradient(transparent, rgba(179,43,34,.14), rgba(179,43,34,.5));\r\n    border-bottom: 1px solid rgba(179,43,34,.72);\r\n    animation: rail-scan 7s linear infinite;\r\n  }\r\n\r\n  @keyframes rail-scan { to { transform: translateY(calc(100vh + 80px)); } }\r\n\r\n  .site-nav__identity {\r\n    position: relative;\r\n    z-index: 1;\r\n    display: grid;\r\n    height: 58px;\r\n    grid-template-columns: 54px 1fr;\r\n    gap: 0;\r\n    align-items: center;\r\n  }\r\n\r\n  .site-nav__mark {\r\n    position: relative;\r\n    width: 42px;\r\n    height: 42px;\r\n    margin-left: 6px;\r\n    border: 0;\r\n    transition: transform 440ms cubic-bezier(.18,.78,.2,1);\r\n  }\r\n\r\n  .site-nav:hover .site-nav__mark,\r\n  .site-nav:focus-within .site-nav__mark { transform: rotate(-3deg) scale(1.04); }\r\n\r\n  .site-nav__mark img { width: 38px; height: 41px; }\r\n\r\n  .site-nav__name {\r\n    width: 160px;\r\n    margin-left: 9px;\r\n    opacity: 0;\r\n    font-size: .58rem;\r\n    font-weight: 600;\r\n    letter-spacing: .13em;\r\n    line-height: 1.45;\r\n    transform: translateX(-10px);\r\n    transition: opacity 180ms ease, transform 360ms cubic-bezier(.18,.78,.2,1);\r\n  }\r\n\r\n  .site-nav__hint {\r\n    position: absolute;\r\n    top: 23px;\r\n    left: 62px;\r\n    width: 94px;\r\n    color: var(--ink-soft);\r\n    font-size: .42rem;\r\n    letter-spacing: .08em;\r\n    white-space: nowrap;\r\n    transform: rotate(90deg) translateY(-9px);\r\n    transform-origin: left top;\r\n    transition: opacity 160ms ease;\r\n  }\r\n\r\n  .site-nav:hover .site-nav__name,\r\n  .site-nav:focus-within .site-nav__name,\r\n  .site-nav.is-peeking .site-nav__name { opacity: 1; transform: translateX(0); transition-delay: 90ms; }\r\n  .site-nav:hover .site-nav__hint,\r\n  .site-nav:focus-within .site-nav__hint { opacity: 0; }\r\n\r\n  .site-nav nav {\r\n    position: relative;\r\n    z-index: 2;\r\n    display: grid;\r\n    gap: 7px;\r\n    margin: clamp(3rem,13vh,7rem) 0 0;\r\n  }\r\n\r\n  .site-nav__item {\r\n    position: relative;\r\n    display: grid;\r\n    width: 246px;\r\n    height: 54px;\r\n    grid-template-columns: 20px 34px 1fr 18px;\r\n    gap: 0;\r\n    align-items: center;\r\n    padding: 0 10px 0 4px;\r\n    overflow: visible;\r\n    border: 0;\r\n    background: transparent;\r\n    color: var(--ink);\r\n    isolation: isolate;\r\n    transition: color 180ms ease, transform 240ms cubic-bezier(.2,.75,.25,1);\r\n  }\r\n\r\n  .site-nav__item::before {\r\n    position: absolute;\r\n    z-index: -1;\r\n    inset: 0;\r\n    content: '';\r\n    background: var(--ink);\r\n    opacity: 0;\r\n    transform: scaleX(.72);\r\n    transform-origin: left;\r\n    transition: opacity 180ms ease, transform 320ms cubic-bezier(.18,.78,.2,1);\r\n  }\r\n\r\n  .site-nav__item::after {\r\n    position: absolute;\r\n    top: 50%;\r\n    left: -4px;\r\n    width: 3px;\r\n    height: 0;\r\n    content: '';\r\n    background: #b32b22;\r\n    transform: translateY(-50%);\r\n    transition: height 250ms ease;\r\n  }\r\n\r\n  .site-nav__item:hover,\r\n  .site-nav__item:focus-visible,\r\n  .site-nav__item.is-active { color: var(--paper); background: transparent; outline: 0; }\r\n  .site-nav__item:hover::before,\r\n  .site-nav__item:focus-visible::before,\r\n  .site-nav__item.is-active::before { opacity: 1; transform: scaleX(1); }\r\n  .site-nav__item.is-active::after { height: 24px; }\r\n  .site-nav__item:hover { transform: translateX(4px); }\r\n\r\n  .nav-index {\r\n    color: var(--ink-soft);\r\n    font-size: .43rem;\r\n    font-variant-numeric: tabular-nums;\r\n    transition: color 180ms;\r\n  }\r\n\r\n  .nav-icon {\r\n    display: grid;\r\n    width: 30px;\r\n    height: 30px;\r\n    place-items: center;\r\n    border: 1px solid rgba(17,18,16,.3);\r\n    font-family: var(--sans);\r\n    font-size: .95rem;\r\n    line-height: 1;\r\n    transition: border-color 180ms, transform 240ms cubic-bezier(.2,.75,.25,1);\r\n  }\r\n\r\n  .site-nav__item:hover .nav-icon { transform: rotate(-5deg) scale(1.05); }\r\n  .site-nav__item:hover .nav-index,\r\n  .site-nav__item:focus-visible .nav-index,\r\n  .site-nav__item.is-active .nav-index { color: rgba(233,231,223,.5); }\r\n  .site-nav__item:hover .nav-icon,\r\n  .site-nav__item:focus-visible .nav-icon,\r\n  .site-nav__item.is-active .nav-icon { border-color: rgba(233,231,223,.35); }\r\n\r\n  .nav-label {\r\n    padding-left: 13px;\r\n    opacity: 0;\r\n    font-size: .64rem;\r\n    letter-spacing: .11em;\r\n    white-space: nowrap;\r\n    transform: translateX(-8px);\r\n    transition: opacity 150ms ease, transform 300ms cubic-bezier(.18,.78,.2,1);\r\n  }\r\n\r\n  .nav-arrow {\r\n    opacity: 0;\r\n    font-size: .72rem;\r\n    transform: translate(-7px,7px);\r\n    transition: opacity 160ms, transform 260ms cubic-bezier(.2,.75,.25,1);\r\n  }\r\n\r\n  .site-nav:hover .nav-label,\r\n  .site-nav:focus-within .nav-label,\r\n  .site-nav.is-peeking .nav-label { opacity: 1; transform: translateX(0); }\r\n  .site-nav:hover .nav-arrow,\r\n  .site-nav:focus-within .nav-arrow,\r\n  .site-nav.is-peeking .nav-arrow { opacity: .58; transform: translate(0,0); }\r\n  .site-nav__item:hover .nav-arrow { opacity: 1; transform: translate(2px,-2px); }\r\n\r\n  .site-nav__footer {\r\n    position: relative;\r\n    z-index: 2;\r\n    display: grid;\r\n    width: 246px;\r\n    grid-template-columns: 1fr auto;\r\n    margin-top: auto;\r\n    padding: 1rem 10px 0 11px;\r\n    border-top: 1px solid rgba(17,18,16,.2);\r\n    align-items: end;\r\n  }\r\n\r\n  .site-nav__status { display: flex; margin: 0; align-items: center; white-space: nowrap; }\r\n  .site-nav__status i { flex: 0 0 auto; margin-right: 18px; animation: status-pulse 2s infinite; }\r\n  .site-nav__status span,\r\n  .site-nav__coord { opacity: 0; transform: translateX(-7px); transition: opacity 180ms ease, transform 300ms ease; }\r\n  .site-nav:hover .site-nav__status span,\r\n  .site-nav:hover .site-nav__coord,\r\n  .site-nav:focus-within .site-nav__status span,\r\n  .site-nav:focus-within .site-nav__coord { opacity: 1; transform: translateX(0); transition-delay: 100ms; }\r\n  .site-nav__coord { margin: 0; color: var(--ink-soft); font-size: .43rem; line-height: 1.5; text-align: right; }\r\n\r\n  .sheet { padding-left: var(--rail-width); transition: padding-left 440ms cubic-bezier(.18,.78,.2,1); }\r\n}\r\n\r\n@media (max-width: 820px) {\r\n  .site-nav { height: 66px; padding: 0 .75rem; border-bottom: 1px solid rgba(17,18,16,.25); box-shadow: 0 8px 30px rgba(17,18,16,.08); }\r\n  .nav-scan,.site-nav__hint,.site-nav__footer,.nav-index,.nav-label,.nav-arrow { display: none; }\r\n  .site-nav__identity { flex: 0 0 auto; }\r\n  .site-nav nav { gap: .25rem; }\r\n  .site-nav__item { display: grid; width: 42px; height: 42px; padding: 0; place-items: center; border: 0; }\r\n  .nav-icon { display: grid!important; width: 34px; height: 34px; place-items: center; border: 1px solid rgba(17,18,16,.2); font-family: var(--sans); font-size: .85rem; }\r\n  .site-nav__item.is-active .nav-icon { color: var(--paper); background: var(--ink); }\r\n  .sheet { padding-top: 66px; }\r\n}\r\n\r\n@media (max-width: 460px) {\r\n  .site-nav { padding: 0 .45rem; }\r\n  .site-nav__mark { width: 32px; height: 36px; }\r\n  .site-nav__mark img { width: 30px; height: 33px; }\r\n  .site-nav__mark b { font-size: .34rem; }\r\n  .site-nav nav { gap: .05rem; }\r\n  .site-nav__item { width: 36px; }\r\n  .nav-icon { width: 30px; height: 30px; font-size: .75rem; }\r\n}\r\n","type":"text/css; charset=utf-8"},"/script.js":{"body":"/* ================================================================\r\n   ARG CONFIGURATION — THE VALUES PLAYTESTS NEED TO SWAP\r\n   ================================================================ */\r\nconst CONFIG = {\r\n  /* The station countdown and the Aquarium opening point at the same moment. */\r\n  targetDate: '2026-09-26T00:00:00-04:00',\r\n  locale: 'zh-CN',\r\n  latestPacket: '0008',\r\n  latestIssued: '09/16/2026',\r\n  archiveAccessKey: 'A17EE71A',\r\n  aquariumUrl: '/aquarium/',\r\n  aquariumLabel: 'etcweatherobservation.com/aquarium',\r\n};\r\n\r\nconst STORAGE_KEYS = {\r\n  firstContact: 'etc-first-contact-complete',\r\n  archiveUnlocked: 'etc-archive-unlocked',\r\n  andrewId: 'etc-andrew-id',\r\n};\r\n\r\nconst ANDREW_DOMAIN = '@andrew.cmu.edu';\r\nconst ALLOWED_USERNAME = /^[A-Za-z0-9._+-]+$/;\r\n/* Private browsing and blocked-storage settings make localStorage throw on\n   access, so every read and write is guarded: if storage is unusable the\r\n   experience still runs, it just forgets progress between visits. */\r\nconst store = {\r\n  get(key) {\r\n    try {\r\n      return window.localStorage.getItem(key);\r\n    } catch {\r\n      return null;\r\n    }\r\n  },\r\n  set(key, value) {\r\n    try {\r\n      window.localStorage.setItem(key, value);\r\n    } catch {\r\n      /* Storage unavailable — progress is lost on reload, nothing else breaks. */\r\n    }\r\n  },\r\n  clear() {\r\n    try {\r\n      Object.values(STORAGE_KEYS).forEach((key) => window.localStorage.removeItem(key));\r\n    } catch {\r\n      /* Nothing to clear. */\r\n    }\r\n  },\r\n};\r\n\r\n/* ?reset=true wipes local progress so a playtest can start from first contact. */\r\nif (new URLSearchParams(location.search).get('reset') === 'true') {\r\n  store.clear();\r\n  try {\r\n    window.localStorage.removeItem('aquarium-visitor');\r\n  } catch {\r\n    /* Aquarium state lives on the same origin but may be unreachable. */\r\n  }\r\n  history.replaceState(null, '', location.pathname + location.hash);\r\n}\r\n\r\n/* ================================================================\r\n   PACKET DATA — ADD NEW RECORDS HERE\r\n   ================================================================ */\r\nconst PACKETS = [\r\n  {\r\n    id: '0008',\r\n    issueDate: '09/16/2026',\r\n    isoDate: '2026-09-16',\r\n    title: 'RETURN OBSERVATION',\r\n    restricted: false,\r\n    pages: ['./packets/packet-0008-1.png'],\r\n  },\r\n  {\r\n    id: '0007',\r\n    issueDate: '09/07/2026',\r\n    isoDate: '2026-09-07',\r\n    title: 'LOCAL FORECAST BULLETIN',\r\n    restricted: false,\r\n    pages: ['./packets/packet-0007-1.png', './packets/packet-0007-2.png'],\r\n  },\r\n  {\r\n    id: '0006',\r\n    issueDate: '09/03/2026',\r\n    isoDate: '2026-09-03',\r\n    title: 'LOCAL FORECAST BULLETIN',\r\n    restricted: false,\r\n    pages: ['./packets/packet-0006-1.png', './packets/packet-0006-2.png'],\r\n  },\r\n  {\r\n    id: '0005',\r\n    issueDate: '08/30/2026',\r\n    isoDate: '2026-08-30',\r\n    title: 'LOCAL FORECAST BULLETIN',\r\n    restricted: false,\r\n    pages: ['./packets/packet-0005-1.png'],\r\n  },\r\n  {\r\n    id: '0004',\r\n    issueDate: '08/27/2026',\r\n    isoDate: '2026-08-27',\r\n    title: 'LOCAL FORECAST BULLETIN',\r\n    restricted: false,\r\n    pages: ['./packets/packet-0004-1.png'],\r\n  },\r\n  {\r\n    id: '0003',\r\n    issueDate: '08/24/2026',\r\n    isoDate: '2026-08-24',\r\n    title: 'LOCAL FORECAST BULLETIN',\r\n    restricted: false,\r\n    pages: ['./packets/packet-0003-1.png'],\r\n  },\r\n  {\r\n    id: '0002',\r\n    issueDate: '10/18/2008',\r\n    isoDate: '2008-10-18',\r\n    title: 'RECOVERED CONVERSATION',\r\n    restricted: true,\r\n    record: {\r\n      timestamp: '10.18.2008 / 2:11',\r\n      source: 'UNRESOLVED',\r\n      state: 'PARTIAL',\r\n      label: 'MESSAGE 02 / REPLY',\r\n      lines: [\r\n        'I CHANGED IT.',\r\n        'I TRACED YOUR SIGNAL TO THE OLD AQUARIUM.',\r\n        'THE SIGNAL STABILIZES',\r\n        'AT  THE  LARGE  G_A_S.',\r\n        'IF THE SAME PLACE EXISTS THERE,',\r\n        'COME  TO  THE  GL_S_  TOMORROW AT 18:00.',\r\n        'WE MAY BE ABLE TO SYNCHRONIZE THE—',\r\n      ],\r\n      symbol: 'rain',\r\n      temperature: '58°F',\r\n      footnote: 'NO FURTHER PAEKETS RECOVERE',\r\n      checksum: 'CHK: E71A',\r\n      relatedRecord: true,\r\n    },\r\n  },\r\n  {\r\n    id: '0001',\r\n    issueDate: '10/17/2008',\r\n    isoDate: '2008-10-17',\r\n    title: 'RECOVERED CONVERSATION',\r\n    restricted: true,\r\n    record: {\r\n      timestamp: '10.17.2008 / 21:43',\r\n      source: 'UNRESOLVED',\r\n      state: 'RECEIVED',\r\n      label: 'MESSAGE 01',\r\n      lines: [\r\n        'THIS IS NOT THE FORECAST I SAVED.',\r\n        'IF SOMEONE ELSE CAN READ THIS',\r\n        \"CHANGE TOMORROW'S SYMBOL TO RAIN.\",\r\n        'DO NOT CHANGE THE TEMPERATURE.',\r\n        'I NEED TO KNOW THIS IS NOT AN ERROR.',\r\n      ],\r\n      symbol: 'sun',\r\n      temperature: '58°F',\r\n      footnote: 'REPLY RECOVERED IN ANOTHER PACKET',\r\n      checksum: 'CHK: A17E',\r\n    },\r\n  },\r\n];\r\n\r\n/* ================================================================\r\n   COUNTDOWN\r\n   ================================================================ */\r\nconst elements = {\r\n  body: document.body,\r\n  hours: document.querySelector('#hours'),\r\n  minutes: document.querySelector('#minutes'),\r\n  seconds: document.querySelector('#seconds'),\r\n  targetDisplay: document.querySelector('#target-display'),\r\n  statusLabel: document.querySelector('#status-label'),\r\n  issuedDate: document.querySelector('#issued-date'),\r\n  packetId: document.querySelector('#packet-id'),\r\n  checksum: document.querySelector('#checksum'),\r\n  syncState: document.querySelector('#sync-state'),\r\n};\r\n\r\nfunction pad(value, size = 2) {\n  return String(value).padStart(size, '0');\n}\n\nfunction makeChecksum(value) {\n  let hash = 2166136261;\r\n  for (const character of value) {\r\n    hash ^= character.charCodeAt(0);\r\n    hash = Math.imul(hash, 16777619);\r\n  }\r\n  const hex = (hash >>> 0).toString(16).toUpperCase().padStart(8, '0');\r\n  return `${hex.slice(0, 4)}-${hex.slice(4)}`;\r\n}\r\n\r\nfunction updateStaticDetails() {\n  elements.hours.textContent = '00';\n  elements.minutes.textContent = '00';\n  elements.seconds.textContent = '00';\n  elements.targetDisplay.textContent = 'NOT SCHEDULED';\n  elements.statusLabel.textContent = 'SUSPENDED';\n  elements.issuedDate.textContent = CONFIG.latestIssued;\n  elements.packetId.textContent = CONFIG.latestPacket;\n  elements.checksum.textContent = makeChecksum(`SUSPENDED:${CONFIG.targetDate}`);\n  elements.syncState.textContent = 'HALTED';\n  elements.hours.closest('.timer').setAttribute('aria-label', 'Next update bulletin suspended');\n}\n\nupdateStaticDetails();\n\r\n/* ================================================================\r\n   ANDREW ID / AFFILIATION\r\n   ================================================================ */\r\nfunction setFormStatus(status, message, type = '') {\r\n  status.textContent = message;\r\n  status.className = `email-form__status${type ? ` is-${type}` : ''}`;\r\n}\r\n\r\nfunction validateUsername(rawValue) {\r\n  const username = rawValue.trim();\r\n\r\n  if (!username) {\r\n    return { valid: false, message: 'Please enter your Andrew ID.' };\r\n  }\r\n  if (username.includes('@')) {\r\n    return { valid: false, message: 'Do not include @ in your Andrew ID.' };\r\n  }\r\n  if (!ALLOWED_USERNAME.test(username)) {\r\n    return {\r\n      valid: false,\r\n      message: 'Use only letters, numbers, periods, underscores, plus signs, and hyphens.',\r\n    };\r\n  }\r\n  if (username.startsWith('.') || username.endsWith('.') || username.includes('..')) {\r\n    return {\r\n      valid: false,\r\n      message: 'Your Andrew ID cannot start or end with a period, or contain consecutive periods.',\r\n    };\r\n  }\r\n\r\n  return { valid: true, username };\r\n}\r\n\r\nfunction wireEmailForm(form, { onSuccess } = {}) {\r\n  const input = form.querySelector('.email-address input');\r\n  const submit = form.querySelector('.submit-button');\r\n  const status = form.querySelector('.email-form__status');\r\n  const submitLabel = submit.textContent;\r\n\r\n  input.addEventListener('beforeinput', (event) => {\r\n    if (event.data?.includes('@')) {\r\n      event.preventDefault();\r\n      input.setAttribute('aria-invalid', 'true');\r\n      setFormStatus(status, 'Do not include @ in your Andrew ID.', 'error');\r\n    }\r\n  });\r\n\r\n  input.addEventListener('input', () => {\r\n    const originalValue = input.value;\r\n    const sanitizedValue = originalValue.replace(/@/g, '').replace(/[^A-Za-z0-9._+-]/g, '');\r\n\r\n    if (sanitizedValue !== originalValue) {\r\n      input.value = sanitizedValue;\r\n      input.setAttribute('aria-invalid', 'true');\r\n      setFormStatus(status, 'Use only letters, numbers, periods, underscores, plus signs, and hyphens.', 'error');\r\n      return;\r\n    }\r\n\r\n    input.removeAttribute('aria-invalid');\r\n    setFormStatus(status, '');\r\n  });\r\n\r\n  form.addEventListener('submit', async (event) => {\r\n    event.preventDefault();\r\n    const validation = validateUsername(input.value);\r\n\r\n    if (!validation.valid) {\r\n      input.setAttribute('aria-invalid', 'true');\r\n      setFormStatus(status, validation.message, 'error');\r\n      input.focus();\r\n      return;\r\n    }\r\n\r\n    const completeEmail = `${validation.username}${ANDREW_DOMAIN}`;\r\n    const submittedAt = new Date();\r\n    const formData = new FormData();\r\n    formData.append('email', completeEmail);\r\n    formData.append('submittedAt', submittedAt.toISOString());\r\n    formData.append('submittedLocal', submittedAt.toString());\r\n\r\n    input.value = validation.username;\r\n    input.removeAttribute('aria-invalid');\r\n    submit.disabled = true;\r\n    submit.textContent = 'VERIFYING...';\r\n    setFormStatus(status, '');\r\n\r\n    /* The record is logged for the production team, but a Formspree outage must\r\n       never strand a player: verification succeeds either way. */\r\n    try {\r\n      await fetch(form.action, {\r\n        method: 'POST',\r\n        headers: { Accept: 'application/json' },\r\n        body: formData,\r\n      });\r\n    } catch {\r\n      /* Offline or blocked — continue without the record. */\r\n    }\r\n\r\n    submit.disabled = false;\r\n    submit.textContent = submitLabel;\r\n    onSuccess?.(validation.username);\r\n  });\r\n}\r\n\r\nconst affiliationForm = document.querySelector('#affiliation-form');\r\nconst affiliationResult = document.querySelector('#affiliation-result');\r\nconst affiliationUsername = document.querySelector('#affiliation-username');\r\nconst affiliationKey = document.querySelector('#affiliation-key');\r\nconst affiliationStatus = document.querySelector('#affiliation-status');\r\n\r\nfunction showAffiliation(username) {\r\n  affiliationUsername.textContent = username;\r\n  affiliationKey.textContent = CONFIG.archiveAccessKey;\r\n  affiliationResult.hidden = false;\r\n}\r\n\r\nwireEmailForm(affiliationForm, {\r\n  onSuccess: (username) => {\r\n    store.set(STORAGE_KEYS.andrewId, username);\r\n    affiliationForm.querySelector('.email-address input').value = '';\r\n    setFormStatus(affiliationStatus, '');\r\n    showAffiliation(username);\r\n  },\r\n});\r\n\r\nconst savedAndrewId = store.get(STORAGE_KEYS.andrewId);\r\nif (savedAndrewId) showAffiliation(savedAndrewId);\r\n\r\n/* ================================================================\r\n   VIEW ROUTING\r\n   ================================================================ */\r\nconst ROUTES = ['current', 'archive', 'about'];\nconst navItems = [...document.querySelectorAll('[data-route]')];\r\nconst views = [...document.querySelectorAll('[data-view]')];\r\n\r\nfunction showView(route, { updateHash = true } = {}) {\r\n  /* #home kept working for anyone holding an old link. */\r\n  const requested = route === 'home' ? 'current' : route;\r\n  const nextRoute = ROUTES.includes(requested) ? requested : 'current';\r\n  views.forEach((view) => view.classList.toggle('is-active', view.dataset.view === nextRoute));\r\n  navItems.forEach((item) => {\r\n    const active = item.dataset.route === nextRoute;\r\n    item.classList.toggle('is-active', active);\r\n    item.setAttribute('aria-current', active ? 'page' : 'false');\r\n  });\r\n  document.title = nextRoute === 'current' ? 'ETC Weather Observation' : `${nextRoute.replace('-', ' ').toUpperCase()} — ETC Observation`;\r\n  if (updateHash) history.replaceState(null, '', `#${nextRoute}`);\r\n  window.scrollTo({ top: 0, behavior: 'smooth' });\r\n}\r\n\r\nnavItems.forEach((item) => item.addEventListener('click', () => showView(item.dataset.route)));\r\nwindow.addEventListener('hashchange', () => showView(location.hash.slice(1), { updateHash: false }));\r\nshowView(location.hash.slice(1) || 'current', { updateHash: false });\r\n\r\n/* ================================================================\r\n   ARCHIVE\r\n   ================================================================ */\r\nconst archiveList = document.querySelector('#archive-list');\r\nconst archiveCode = document.querySelector('#archive-code');\r\nconst archiveNote = document.querySelector('#archive-note');\r\nconst packetViewer = document.querySelector('#packet-viewer');\r\nconst packetViewerClose = document.querySelector('#packet-viewer-close');\r\nconst packetViewerMeta = document.querySelector('#packet-viewer-meta');\r\nconst packetViewerTitle = document.querySelector('#packet-viewer-title');\r\nconst packetViewerPages = document.querySelector('#packet-viewer-pages');\r\nconst restrictedDialog = document.querySelector('#restricted-dialog');\r\nconst restrictedClose = document.querySelector('#restricted-close');\r\nconst archiveForm = document.querySelector('#archive-form');\r\nconst archiveKeyInput = document.querySelector('#archive-key');\r\nconst archiveStatus = document.querySelector('#archive-status');\r\n\r\nfunction isArchiveUnlocked() {\r\n  return store.get(STORAGE_KEYS.archiveUnlocked) === 'true';\r\n}\r\n\r\nfunction renderArchive() {\r\n  const unlocked = isArchiveUnlocked();\r\n  const withheld = PACKETS.filter((packet) => packet.restricted && !unlocked).length;\r\n\r\n  archiveList.replaceChildren(\r\n    ...PACKETS.map((packet) => {\r\n      const locked = packet.restricted && !unlocked;\r\n      const link = document.createElement('a');\r\n      link.className = `archive-link${locked ? ' is-restricted' : ''}`;\r\n      link.href = `#packet-${packet.id}`;\r\n      link.dataset.packet = packet.id;\r\n\r\n      const name = document.createElement('strong');\r\n      name.textContent = `PACKET ${packet.id}`;\r\n\r\n      const date = document.createElement('time');\r\n      date.dateTime = packet.isoDate;\r\n      date.textContent = packet.issueDate;\r\n\r\n      const state = document.createElement('span');\r\n      state.textContent = locked ? '[RESTRICTED]' : '[VIEW]';\r\n\r\n      link.append(name, date, state);\r\n      link.addEventListener('click', (event) => {\r\n        event.preventDefault();\r\n        if (packet.restricted && !isArchiveUnlocked()) {\r\n          openRestrictedDialog();\r\n          return;\r\n        }\r\n        openPacket(packet);\r\n      });\r\n      return link;\r\n    }),\r\n  );\r\n\r\n  archiveCode.textContent = `${pad(PACKETS.length)} RECORDS / READ ONLY`;\r\n  archiveNote.textContent = withheld\r\n    ? `${pad(withheld)} RECORDS WITHHELD / OPERATOR ACCESS REQUIRED`\r\n    : 'ARCHIVE ACCESS GRANTED / ALL RECORDS AVAILABLE';\r\n  archiveNote.dataset.state = withheld ? 'withheld' : 'granted';\r\n}\r\n\r\nfunction createSymbol(kind) {\r\n  const namespace = 'http://www.w3.org/2000/svg';\r\n  const svg = document.createElementNS(namespace, 'svg');\r\n  svg.setAttribute('viewBox', '0 0 120 120');\r\n  svg.setAttribute('class', 'recovered-symbol');\r\n  svg.setAttribute('aria-hidden', 'true');\r\n\r\n  if (kind === 'sun') {\r\n    const points = [];\r\n    for (let index = 0; index < 24; index += 1) {\r\n      const radius = index % 2 === 0 ? 56 : 38;\r\n      const angle = (Math.PI * index) / 12 - Math.PI / 2;\r\n      points.push(`${(60 + radius * Math.cos(angle)).toFixed(1)},${(60 + radius * Math.sin(angle)).toFixed(1)}`);\r\n    }\r\n    const burst = document.createElementNS(namespace, 'polygon');\r\n    burst.setAttribute('points', points.join(' '));\r\n    const core = document.createElementNS(namespace, 'circle');\r\n    core.setAttribute('cx', '60');\r\n    core.setAttribute('cy', '60');\r\n    core.setAttribute('r', '24');\r\n    svg.append(burst, core);\r\n    return svg;\r\n  }\r\n\r\n  const cloud = document.createElementNS(namespace, 'path');\r\n  cloud.setAttribute(\r\n    'd',\r\n    'M30 74 C15 74 10 60 21 53 C16 37 34 27 46 36 C52 20 78 22 82 40 C99 38 105 60 92 68 C89 72 84 74 78 74 Z',\r\n  );\r\n  svg.append(cloud);\r\n\r\n  [30, 44, 58, 72, 86].forEach((x) => {\r\n    const drop = document.createElementNS(namespace, 'line');\r\n    drop.setAttribute('x1', String(x));\r\n    drop.setAttribute('y1', '84');\r\n    drop.setAttribute('x2', String(x - 7));\r\n    drop.setAttribute('y2', '102');\r\n    svg.append(drop);\r\n  });\r\n\r\n  return svg;\r\n}\r\n\r\nfunction createRecoveredSheet(packet) {\r\n  const { record } = packet;\r\n  const sheet = document.createElement('article');\r\n  sheet.className = 'recovered';\r\n\r\n  const head = document.createElement('header');\r\n  head.className = 'recovered__head';\r\n  head.innerHTML = '<b>ETC WEATHER OBSERVATION</b><span>ARCHIVE / 2008</span>';\r\n\r\n  const body = document.createElement('div');\r\n  body.className = 'recovered__body';\r\n\r\n  const tags = document.createElement('div');\r\n  tags.className = 'recovered__tags';\r\n  tags.innerHTML = `<span>RECOVERED CONVERSATION</span><span>PACKET ${packet.id}</span>`;\r\n\r\n  const meta = document.createElement('dl');\r\n  meta.className = 'recovered__meta';\r\n  meta.innerHTML = `\r\n    <div><dt>DATE</dt><dd>${record.timestamp}</dd></div>\r\n    <div><dt>SOURCE</dt><dd>${record.source}</dd></div>\r\n    <div><dt>STATE</dt><dd>${record.state}</dd></div>`;\r\n\r\n  const grid = document.createElement('div');\r\n  grid.className = 'recovered__grid';\r\n\r\n  const message = document.createElement('div');\r\n  message.className = 'recovered__message';\r\n  const label = document.createElement('p');\r\n  label.className = 'recovered__label';\r\n  label.textContent = record.label;\r\n  message.append(label, ...record.lines.map((line) => {\r\n    const paragraph = document.createElement('p');\r\n    paragraph.className = 'recovered__line';\r\n    paragraph.textContent = line;\r\n    return paragraph;\r\n  }));\r\n\r\n  const figure = document.createElement('figure');\r\n  figure.className = 'recovered__glass';\r\n  const caption = document.createElement('figcaption');\r\n  caption.textContent = record.temperature;\r\n  figure.append(createSymbol(record.symbol), caption);\r\n\r\n  grid.append(message, figure);\r\n\r\n  const foot = document.createElement('footer');\r\n  foot.className = 'recovered__foot';\r\n  foot.innerHTML = `<span>${record.footnote}</span><span>${record.checksum}</span>`;\r\n\r\n  body.append(tags, meta, grid, foot);\r\n  sheet.append(head, body);\r\n  return sheet;\r\n}\r\n\r\nfunction createRelatedRecord() {\r\n  const related = document.createElement('aside');\r\n  related.className = 'related-record';\r\n\r\n  const label = document.createElement('p');\r\n  label.className = 'related-record__label';\r\n  label.textContent = 'RELATED RECORD';\r\n\r\n  const link = document.createElement('a');\r\n  link.className = 'related-record__link';\r\n  link.href = CONFIG.aquariumUrl;\r\n  link.textContent = CONFIG.aquariumLabel;\r\n\r\n  const note = document.createElement('p');\r\n  note.className = 'related-record__note';\r\n  note.textContent = 'LOCATION REFERENCED IN THIS MESSAGE / STILL RESOLVING';\r\n\r\n  related.append(label, link, note);\r\n  return related;\r\n}\r\n\r\nfunction openPacket(packet) {\r\n  packetViewerMeta.textContent = `PACKET ${packet.id} / ${packet.issueDate}`;\r\n  packetViewerTitle.textContent = packet.title;\r\n\r\n  const pages = [];\r\n\r\n  if (packet.record) {\n    const recovered = createRecoveredSheet(packet);\n    if (packet.record.relatedRecord) {\n      const packetStack = document.createElement('div');\n      packetStack.className = 'packet-record-stack';\n      packetStack.append(recovered, createRelatedRecord());\n      pages.push(packetStack);\n    } else {\n      pages.push(recovered);\n    }\n  } else {\r\n    packet.pages.forEach((source, index) => {\r\n      const figure = document.createElement('figure');\r\n      figure.className = 'packet-page';\r\n\r\n      const image = document.createElement('img');\r\n      image.src = source;\r\n      image.loading = index === 0 ? 'eager' : 'lazy';\r\n      image.alt = `Packet ${packet.id}, issued ${packet.issueDate}${packet.pages.length > 1 ? `, page ${index + 1}` : ''}`;\r\n      figure.append(image);\r\n\r\n      if (packet.pages.length > 1) {\r\n        const caption = document.createElement('figcaption');\r\n        caption.textContent = `PAGE ${index + 1} / ${packet.pages.length}`;\r\n        figure.append(caption);\r\n      }\r\n      pages.push(figure);\r\n    });\r\n  }\r\n\r\n  packetViewerPages.replaceChildren(...pages);\r\n  packetViewer.showModal();\r\n  packetViewer.querySelector('.packet-viewer__card').scrollTop = 0;\r\n}\r\n\r\nfunction closePacketViewer() {\r\n  packetViewer.close();\r\n}\r\n\r\nfunction openRestrictedDialog() {\r\n  archiveKeyInput.value = '';\r\n  archiveStatus.textContent = '';\r\n  archiveStatus.removeAttribute('data-state');\r\n  restrictedDialog.showModal();\r\n  window.setTimeout(() => archiveKeyInput.focus(), 0);\r\n}\r\n\r\nfunction closeRestrictedDialog() {\r\n  restrictedDialog.close();\r\n}\r\n\r\npacketViewerClose.addEventListener('click', closePacketViewer);\r\npacketViewer.addEventListener('click', (event) => {\r\n  if (event.target === packetViewer) closePacketViewer();\r\n});\r\npacketViewer.addEventListener('close', () => packetViewerPages.replaceChildren());\r\n\r\nrestrictedClose.addEventListener('click', closeRestrictedDialog);\r\nrestrictedDialog.addEventListener('click', (event) => {\r\n  if (event.target === restrictedDialog) closeRestrictedDialog();\r\n});\r\nrestrictedDialog.addEventListener('close', () => {\r\n  archiveKeyInput.value = '';\r\n});\r\n\r\narchiveForm.addEventListener('submit', (event) => {\r\n  event.preventDefault();\r\n  const entered = archiveKeyInput.value.trim().replace(/[\\s-]/g, '').toUpperCase();\r\n\r\n  if (entered !== CONFIG.archiveAccessKey.replace(/[\\s-]/g, '').toUpperCase()) {\r\n    archiveStatus.textContent = 'ACCESS KEY NOT RECOGNIZED';\r\n    archiveStatus.dataset.state = 'error';\r\n    archiveKeyInput.value = '';\r\n    archiveKeyInput.focus();\r\n    archiveForm.animate(\r\n      [{ transform: 'translateX(-5px)' }, { transform: 'translateX(5px)' }, { transform: 'translateX(0)' }],\r\n      { duration: 180 },\r\n    );\r\n    return;\r\n  }\r\n\r\n  /* One key opens both withheld records — the player never types it twice. */\r\n  store.set(STORAGE_KEYS.archiveUnlocked, 'true');\r\n  renderArchive();\r\n  archiveKeyInput.value = '';\r\n  archiveStatus.innerHTML = 'ARCHIVE ACCESS GRANTED<br />PACKETS 0001–0002 UNLOCKED.';\r\n  archiveStatus.dataset.state = 'success';\r\n  window.setTimeout(closeRestrictedDialog, 2200);\r\n});\r\n\r\nrenderArchive();\r\n\r\n/* ================================================================\r\n   FIRST CONTACT\r\n   ================================================================ */\r\nconst SIGNAL_LINES = [\r\n  'GOOD.',\r\n  'THERE IS SOMEONE THERE.',\r\n  \"I WASN'T SURE.\",\r\n  'OLD RECORDS.',\r\n  'BEFORE THE ONES YOU SAW.',\r\n  'LOOK THERE.',\r\n  'SOMETHING WAS LEFT.',\r\n  'AQUARIUM—',\r\n  '...',\r\n  \"I CAN'T HOLD THIS.\",\r\n];\r\n\r\nconst signalDialog = document.querySelector('#signal-dialog');\r\nconst signalBody = document.querySelector('#signal-body');\r\nconst signalQuestion = document.querySelector('#signal-question');\r\nconst signalActions = document.querySelector('#signal-actions');\r\nconst signalYes = document.querySelector('#signal-yes');\r\nconst signalDismiss = document.querySelector('#signal-dismiss');\r\n\r\nfunction setupFirstContact() {\r\n  if (store.get(STORAGE_KEYS.firstContact) === 'true') return;\r\n\r\n  let closable = false;\r\n\r\n  function appendLine(text) {\r\n    const line = document.createElement('p');\r\n    line.className = 'signal__line';\r\n    line.textContent = text;\r\n    signalBody.append(line);\r\n    signalBody.scrollTop = signalBody.scrollHeight;\r\n  }\r\n\r\n  function endTransmission() {\r\n    signalDialog.classList.add('is-severing');\r\n    /* The dots twitch once more before the connection gives out. */\r\n    window.setTimeout(() => {\r\n      closable = true;\r\n      signalDialog.classList.remove('is-severing');\r\n      signalDialog.classList.add('is-closable');\r\n      signalDismiss.disabled = false;\r\n      signalDismiss.setAttribute('aria-label', 'Close transmission');\r\n      signalDismiss.focus({ preventScroll: true });\r\n    }, 1200);\r\n  }\r\n\r\n  function playTransmission() {\r\n    signalQuestion.remove();\r\n    signalActions.remove();\r\n    signalDialog.classList.add('is-receiving');\r\n\r\n    let delay = 400;\r\n    SIGNAL_LINES.forEach((text, index) => {\r\n      delay += text === '...' ? 1100 : 500 + Math.round(Math.random() * 500);\r\n      window.setTimeout(() => {\r\n        appendLine(text);\r\n        if (index === SIGNAL_LINES.length - 1) endTransmission();\r\n      }, delay);\r\n    });\r\n  }\r\n\r\n  signalYes.addEventListener('click', playTransmission);\r\n\r\n  signalDismiss.addEventListener('click', () => {\r\n    if (!closable) return;\r\n    store.set(STORAGE_KEYS.firstContact, 'true');\r\n    signalDialog.close();\r\n  });\r\n\r\n  /* Escape, backdrop clicks and anything else stay blocked until the\r\n     transmission has run out on its own. */\r\n  signalDialog.addEventListener('cancel', (event) => {\r\n    if (!closable) {\r\n      event.preventDefault();\r\n      return;\r\n    }\r\n    store.set(STORAGE_KEYS.firstContact, 'true');\r\n  });\r\n\r\n  signalDialog.addEventListener('close', () => {\r\n    if (store.get(STORAGE_KEYS.firstContact) !== 'true') signalDialog.showModal();\r\n  });\r\n\r\n  signalDialog.showModal();\r\n}\r\n\r\nsetupFirstContact();\r\n\r\n/* ================================================================\r\n   NAVIGATION RAIL\r\n   ================================================================ */\r\nconst observationRail = document.querySelector('.site-nav');\r\nif (observationRail) {\r\n  observationRail.addEventListener('pointermove', (event) => {\r\n    const bounds = observationRail.getBoundingClientRect();\r\n    observationRail.style.setProperty('--nav-y', `${event.clientY - bounds.top}px`);\r\n  });\r\n\r\n  observationRail.addEventListener('pointerleave', () => {\r\n    observationRail.style.setProperty('--nav-y', '50%');\r\n    observationRail.classList.remove('is-peeking');\r\n    observationRail.querySelector(':focus')?.blur();\r\n  });\r\n\r\n  if (!window.sessionStorage.getItem('etc-rail-seen') && window.matchMedia('(min-width: 821px)').matches) {\r\n    observationRail.classList.add('is-peeking');\r\n    window.setTimeout(() => observationRail.classList.remove('is-peeking'), 1450);\r\n    window.sessionStorage.setItem('etc-rail-seen', 'true');\r\n  }\r\n\r\n  observationRail.addEventListener('keydown', (event) => {\r\n    if (event.key === 'Escape') {\r\n      document.activeElement?.blur();\r\n      observationRail.classList.remove('is-peeking');\r\n    }\r\n  });\r\n}\r\n","type":"text/javascript; charset=utf-8"},"/aquarium":{"body":"<!doctype html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <meta name=\"theme-color\" content=\"#0e3d4e\" />\r\n    <title>AQUARIUM</title>\r\n    <meta name=\"description\" content=\"Aquarium — visitor admission. The Aquarium opens only during the full moon.\" />\r\n    <meta name=\"robots\" content=\"noindex, nofollow\" />\r\n    <link rel=\"icon\" href=\"../icon_black.ico\" sizes=\"any\" />\r\n    <link rel=\"stylesheet\" href=\"./style.css\" />\r\n  </head>\r\n  <body>\r\n    <div class=\"page\">\r\n      <header class=\"banner\">\r\n        <p class=\"banner__mark\">AQUARIUM</p>\r\n        <p class=\"banner__sub\">VISITOR ADMISSION</p>\r\n        <p class=\"banner__est\">ESTABLISHED — RECORD INCOMPLETE</p>\r\n      </header>\r\n\r\n      <nav class=\"menubar\" aria-label=\"Sections\">\r\n        <a class=\"menubar__item is-current\" href=\"#home\">HOME</a>\r\n        <a class=\"menubar__item\" href=\"#opening-cycle\">OPENING CYCLE</a>\r\n      </nav>\r\n\r\n      <main>\r\n        <section class=\"admission\" id=\"home\">\r\n          <div class=\"tank\" aria-hidden=\"true\">\r\n            <div class=\"tank__light\"></div>\r\n            <div class=\"tank__swimmers\">\r\n              <svg class=\"tank__fish tank__fish--a\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n              <svg class=\"tank__fish tank__fish--b\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n              <svg class=\"tank__fish tank__fish--c\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n            </div>\r\n            <p class=\"tank__caption\">MAIN HALL / VIEW FROM THE GLASS</p>\r\n          </div>\r\n\r\n          <div class=\"admission__cta\">\r\n            <button class=\"ticket-button\" id=\"get-ticket\" type=\"button\">GET TICKET</button>\r\n            <p class=\"admission__note\">No payment is collected. Admission is recorded, not sold.</p>\r\n          </div>\r\n        </section>\r\n\r\n        <section class=\"guide\" id=\"opening-cycle\">\r\n          <h2 class=\"section-title\">OPENING CYCLE</h2>\r\n          <div class=\"guide__body\">\r\n            <p>The Aquarium does not maintain regular public hours.</p>\r\n            <p>It opens only during the full moon.</p>\r\n            <p>Outside this period, visitor access remains closed.</p>\r\n            <p>Tickets may be issued at any time. Admission is possible only while the Aquarium is open.</p>\r\n          </div>\r\n\r\n          <div class=\"opening\" aria-labelledby=\"opening-title\">\r\n            <p class=\"opening__label\" id=\"opening-title\">NEXT OPENING</p>\r\n            <p class=\"opening__date\" id=\"opening-date\">SEPTEMBER 26, 2026</p>\r\n            <div class=\"opening__clock\" id=\"opening-clock\" role=\"timer\" aria-live=\"off\">\r\n              <div class=\"opening__unit\"><b id=\"opening-days\">00</b><span>DAYS</span></div>\r\n              <div class=\"opening__unit\"><b id=\"opening-hours\">00</b><span>HOURS</span></div>\r\n              <div class=\"opening__unit\"><b id=\"opening-minutes\">00</b><span>MINUTES</span></div>\r\n            </div>\r\n            <p class=\"opening__state\" id=\"opening-state\">CLOSED UNTIL THE FULL MOON</p>\r\n          </div>\r\n        </section>\r\n      </main>\r\n\r\n      <footer class=\"colophon\">\r\n        <p>THIS PAGE IS MAINTAINED BY THE AQUARIUM.</p>\r\n        <p>LAST UPDATED: <span id=\"last-updated\">10/18/2008</span></p>\r\n        <p class=\"colophon__counter\">VISITORS <span id=\"visitor-counter\">0000000</span></p>\r\n      </footer>\r\n    </div>\r\n\r\n    <div class=\"registration\" id=\"registration\" hidden>\r\n      <div class=\"registration__frame\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"registration-title\">\r\n        <header class=\"registration__head\">\r\n          <p class=\"registration__title\" id=\"registration-title\">VISITOR REGISTRATION</p>\r\n          <p class=\"registration__progress\" id=\"registration-progress\">01 / 13</p>\n          <button class=\"registration__close\" id=\"registration-close\" type=\"button\" aria-label=\"Close registration\">✕</button>\r\n        </header>\r\n        <div class=\"registration__track\" aria-hidden=\"true\"><i id=\"registration-bar\"></i></div>\r\n        <div class=\"registration__body\" id=\"registration-body\"></div>\r\n        <footer class=\"registration__foot\" id=\"registration-foot\">\r\n          <button class=\"flat-button\" id=\"registration-back\" type=\"button\">BACK</button>\r\n          <button class=\"flat-button flat-button--primary\" id=\"registration-next\" type=\"button\">CONTINUE</button>\r\n        </footer>\r\n      </div>\r\n    </div>\r\n\r\n    <noscript>This page needs JavaScript to issue a ticket.</noscript>\r\n    <script type=\"module\" src=\"./script.js\"></script>\r\n  </body>\r\n</html>\r\n","type":"text/html; charset=utf-8"},"/aquarium/":{"body":"<!doctype html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <meta name=\"theme-color\" content=\"#0e3d4e\" />\r\n    <title>AQUARIUM</title>\r\n    <meta name=\"description\" content=\"Aquarium — visitor admission. The Aquarium opens only during the full moon.\" />\r\n    <meta name=\"robots\" content=\"noindex, nofollow\" />\r\n    <link rel=\"icon\" href=\"../icon_black.ico\" sizes=\"any\" />\r\n    <link rel=\"stylesheet\" href=\"./style.css\" />\r\n  </head>\r\n  <body>\r\n    <div class=\"page\">\r\n      <header class=\"banner\">\r\n        <p class=\"banner__mark\">AQUARIUM</p>\r\n        <p class=\"banner__sub\">VISITOR ADMISSION</p>\r\n        <p class=\"banner__est\">ESTABLISHED — RECORD INCOMPLETE</p>\r\n      </header>\r\n\r\n      <nav class=\"menubar\" aria-label=\"Sections\">\r\n        <a class=\"menubar__item is-current\" href=\"#home\">HOME</a>\r\n        <a class=\"menubar__item\" href=\"#opening-cycle\">OPENING CYCLE</a>\r\n      </nav>\r\n\r\n      <main>\r\n        <section class=\"admission\" id=\"home\">\r\n          <div class=\"tank\" aria-hidden=\"true\">\r\n            <div class=\"tank__light\"></div>\r\n            <div class=\"tank__swimmers\">\r\n              <svg class=\"tank__fish tank__fish--a\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n              <svg class=\"tank__fish tank__fish--b\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n              <svg class=\"tank__fish tank__fish--c\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n            </div>\r\n            <p class=\"tank__caption\">MAIN HALL / VIEW FROM THE GLASS</p>\r\n          </div>\r\n\r\n          <div class=\"admission__cta\">\r\n            <button class=\"ticket-button\" id=\"get-ticket\" type=\"button\">GET TICKET</button>\r\n            <p class=\"admission__note\">No payment is collected. Admission is recorded, not sold.</p>\r\n          </div>\r\n        </section>\r\n\r\n        <section class=\"guide\" id=\"opening-cycle\">\r\n          <h2 class=\"section-title\">OPENING CYCLE</h2>\r\n          <div class=\"guide__body\">\r\n            <p>The Aquarium does not maintain regular public hours.</p>\r\n            <p>It opens only during the full moon.</p>\r\n            <p>Outside this period, visitor access remains closed.</p>\r\n            <p>Tickets may be issued at any time. Admission is possible only while the Aquarium is open.</p>\r\n          </div>\r\n\r\n          <div class=\"opening\" aria-labelledby=\"opening-title\">\r\n            <p class=\"opening__label\" id=\"opening-title\">NEXT OPENING</p>\r\n            <p class=\"opening__date\" id=\"opening-date\">SEPTEMBER 26, 2026</p>\r\n            <div class=\"opening__clock\" id=\"opening-clock\" role=\"timer\" aria-live=\"off\">\r\n              <div class=\"opening__unit\"><b id=\"opening-days\">00</b><span>DAYS</span></div>\r\n              <div class=\"opening__unit\"><b id=\"opening-hours\">00</b><span>HOURS</span></div>\r\n              <div class=\"opening__unit\"><b id=\"opening-minutes\">00</b><span>MINUTES</span></div>\r\n            </div>\r\n            <p class=\"opening__state\" id=\"opening-state\">CLOSED UNTIL THE FULL MOON</p>\r\n          </div>\r\n        </section>\r\n      </main>\r\n\r\n      <footer class=\"colophon\">\r\n        <p>THIS PAGE IS MAINTAINED BY THE AQUARIUM.</p>\r\n        <p>LAST UPDATED: <span id=\"last-updated\">10/18/2008</span></p>\r\n        <p class=\"colophon__counter\">VISITORS <span id=\"visitor-counter\">0000000</span></p>\r\n      </footer>\r\n    </div>\r\n\r\n    <div class=\"registration\" id=\"registration\" hidden>\r\n      <div class=\"registration__frame\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"registration-title\">\r\n        <header class=\"registration__head\">\r\n          <p class=\"registration__title\" id=\"registration-title\">VISITOR REGISTRATION</p>\r\n          <p class=\"registration__progress\" id=\"registration-progress\">01 / 13</p>\n          <button class=\"registration__close\" id=\"registration-close\" type=\"button\" aria-label=\"Close registration\">✕</button>\r\n        </header>\r\n        <div class=\"registration__track\" aria-hidden=\"true\"><i id=\"registration-bar\"></i></div>\r\n        <div class=\"registration__body\" id=\"registration-body\"></div>\r\n        <footer class=\"registration__foot\" id=\"registration-foot\">\r\n          <button class=\"flat-button\" id=\"registration-back\" type=\"button\">BACK</button>\r\n          <button class=\"flat-button flat-button--primary\" id=\"registration-next\" type=\"button\">CONTINUE</button>\r\n        </footer>\r\n      </div>\r\n    </div>\r\n\r\n    <noscript>This page needs JavaScript to issue a ticket.</noscript>\r\n    <script type=\"module\" src=\"./script.js\"></script>\r\n  </body>\r\n</html>\r\n","type":"text/html; charset=utf-8"},"/aquarium/index.html":{"body":"<!doctype html>\r\n<html lang=\"en\">\r\n  <head>\r\n    <meta charset=\"UTF-8\" />\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n    <meta name=\"theme-color\" content=\"#0e3d4e\" />\r\n    <title>AQUARIUM</title>\r\n    <meta name=\"description\" content=\"Aquarium — visitor admission. The Aquarium opens only during the full moon.\" />\r\n    <meta name=\"robots\" content=\"noindex, nofollow\" />\r\n    <link rel=\"icon\" href=\"../icon_black.ico\" sizes=\"any\" />\r\n    <link rel=\"stylesheet\" href=\"./style.css\" />\r\n  </head>\r\n  <body>\r\n    <div class=\"page\">\r\n      <header class=\"banner\">\r\n        <p class=\"banner__mark\">AQUARIUM</p>\r\n        <p class=\"banner__sub\">VISITOR ADMISSION</p>\r\n        <p class=\"banner__est\">ESTABLISHED — RECORD INCOMPLETE</p>\r\n      </header>\r\n\r\n      <nav class=\"menubar\" aria-label=\"Sections\">\r\n        <a class=\"menubar__item is-current\" href=\"#home\">HOME</a>\r\n        <a class=\"menubar__item\" href=\"#opening-cycle\">OPENING CYCLE</a>\r\n      </nav>\r\n\r\n      <main>\r\n        <section class=\"admission\" id=\"home\">\r\n          <div class=\"tank\" aria-hidden=\"true\">\r\n            <div class=\"tank__light\"></div>\r\n            <div class=\"tank__swimmers\">\r\n              <svg class=\"tank__fish tank__fish--a\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n              <svg class=\"tank__fish tank__fish--b\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n              <svg class=\"tank__fish tank__fish--c\" viewBox=\"0 0 120 48\"><path d=\"M4 24c18-19 52-22 74-10 8 4 14 9 18 10-4 1-10 6-18 10-22 12-56 9-74-10Z\" /><path d=\"M96 24l20-14v28Z\" /><circle cx=\"28\" cy=\"20\" r=\"2.6\" /></svg>\r\n            </div>\r\n            <p class=\"tank__caption\">MAIN HALL / VIEW FROM THE GLASS</p>\r\n          </div>\r\n\r\n          <div class=\"admission__cta\">\r\n            <button class=\"ticket-button\" id=\"get-ticket\" type=\"button\">GET TICKET</button>\r\n            <p class=\"admission__note\">No payment is collected. Admission is recorded, not sold.</p>\r\n          </div>\r\n        </section>\r\n\r\n        <section class=\"guide\" id=\"opening-cycle\">\r\n          <h2 class=\"section-title\">OPENING CYCLE</h2>\r\n          <div class=\"guide__body\">\r\n            <p>The Aquarium does not maintain regular public hours.</p>\r\n            <p>It opens only during the full moon.</p>\r\n            <p>Outside this period, visitor access remains closed.</p>\r\n            <p>Tickets may be issued at any time. Admission is possible only while the Aquarium is open.</p>\r\n          </div>\r\n\r\n          <div class=\"opening\" aria-labelledby=\"opening-title\">\r\n            <p class=\"opening__label\" id=\"opening-title\">NEXT OPENING</p>\r\n            <p class=\"opening__date\" id=\"opening-date\">SEPTEMBER 26, 2026</p>\r\n            <div class=\"opening__clock\" id=\"opening-clock\" role=\"timer\" aria-live=\"off\">\r\n              <div class=\"opening__unit\"><b id=\"opening-days\">00</b><span>DAYS</span></div>\r\n              <div class=\"opening__unit\"><b id=\"opening-hours\">00</b><span>HOURS</span></div>\r\n              <div class=\"opening__unit\"><b id=\"opening-minutes\">00</b><span>MINUTES</span></div>\r\n            </div>\r\n            <p class=\"opening__state\" id=\"opening-state\">CLOSED UNTIL THE FULL MOON</p>\r\n          </div>\r\n        </section>\r\n      </main>\r\n\r\n      <footer class=\"colophon\">\r\n        <p>THIS PAGE IS MAINTAINED BY THE AQUARIUM.</p>\r\n        <p>LAST UPDATED: <span id=\"last-updated\">10/18/2008</span></p>\r\n        <p class=\"colophon__counter\">VISITORS <span id=\"visitor-counter\">0000000</span></p>\r\n      </footer>\r\n    </div>\r\n\r\n    <div class=\"registration\" id=\"registration\" hidden>\r\n      <div class=\"registration__frame\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"registration-title\">\r\n        <header class=\"registration__head\">\r\n          <p class=\"registration__title\" id=\"registration-title\">VISITOR REGISTRATION</p>\r\n          <p class=\"registration__progress\" id=\"registration-progress\">01 / 13</p>\n          <button class=\"registration__close\" id=\"registration-close\" type=\"button\" aria-label=\"Close registration\">✕</button>\r\n        </header>\r\n        <div class=\"registration__track\" aria-hidden=\"true\"><i id=\"registration-bar\"></i></div>\r\n        <div class=\"registration__body\" id=\"registration-body\"></div>\r\n        <footer class=\"registration__foot\" id=\"registration-foot\">\r\n          <button class=\"flat-button\" id=\"registration-back\" type=\"button\">BACK</button>\r\n          <button class=\"flat-button flat-button--primary\" id=\"registration-next\" type=\"button\">CONTINUE</button>\r\n        </footer>\r\n      </div>\r\n    </div>\r\n\r\n    <noscript>This page needs JavaScript to issue a ticket.</noscript>\r\n    <script type=\"module\" src=\"./script.js\"></script>\r\n  </body>\r\n</html>\r\n","type":"text/html; charset=utf-8"},"/aquarium/style.css":{"body":"/* ================================================================\r\n   AQUARIUM — a municipal website that stopped being updated\r\n   ================================================================ */\r\n:root {\r\n  --deep: #0c3646;\r\n  --deep-dark: #07222d;\r\n  --panel: #f1efe3;\r\n  --panel-edge: #c8c4b0;\r\n  --navy: #17385c;\r\n  --teal: #1f6f7a;\r\n  --ink: #1c1c19;\r\n  --ink-soft: #5c5c52;\r\n  --link: #1a3fa0;\r\n  --brass: #b8912f;\r\n  --serif: 'Times New Roman', Times, Georgia, serif;\r\n  --sans: Verdana, Geneva, 'Segoe UI', sans-serif;\r\n  --mono: 'Courier New', Courier, monospace;\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\nbody {\r\n  min-width: 320px;\r\n  margin: 0;\r\n  padding: clamp(0px, 2vw, 26px);\r\n  background-color: var(--deep);\r\n  background-image:\r\n    repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.035) 0 2px, transparent 2px 9px),\r\n    repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.14) 0 1px, transparent 1px 4px),\r\n    radial-gradient(circle at 50% 0%, #15556a, var(--deep-dark) 78%);\r\n  color: var(--ink);\r\n  font-family: var(--sans);\r\n  font-size: 13px;\r\n  line-height: 1.6;\r\n}\r\n\r\n.page {\r\n  max-width: 780px;\r\n  margin: 0 auto;\r\n  border: 3px ridge #9fb6bb;\r\n  background: var(--panel);\r\n  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.4), 0 14px 40px rgba(0, 0, 0, 0.45);\r\n}\r\n\r\n/* ---------- banner ---------- */\r\n.banner {\r\n  padding: clamp(1.4rem, 5vw, 2.6rem) 1rem clamp(1rem, 3vw, 1.6rem);\r\n  border-bottom: 2px solid var(--navy);\r\n  background:\r\n    radial-gradient(ellipse at 50% 120%, rgba(120, 220, 235, 0.22), transparent 62%),\r\n    linear-gradient(170deg, var(--navy), var(--teal));\r\n  text-align: center;\r\n}\r\n\r\n.banner p {\r\n  margin: 0;\r\n}\r\n\r\n.banner__mark {\r\n  color: #fff;\r\n  font-family: var(--serif);\r\n  font-size: clamp(2.4rem, 12vw, 4.6rem);\r\n  font-weight: 400;\r\n  letter-spacing: clamp(0.12em, 2vw, 0.3em);\r\n  line-height: 1;\r\n  text-indent: clamp(0.12em, 2vw, 0.3em);\r\n  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.35);\r\n}\r\n\r\n.banner__sub {\r\n  margin-top: 0.9rem;\r\n  color: #cfe9ee;\r\n  font-size: clamp(0.6rem, 2.4vw, 0.75rem);\r\n  letter-spacing: 0.42em;\r\n  text-indent: 0.42em;\r\n}\r\n\r\n.banner__est {\r\n  margin-top: 0.5rem;\r\n  color: rgba(207, 233, 238, 0.55);\r\n  font-size: 0.56rem;\r\n  letter-spacing: 0.2em;\r\n}\r\n\r\n/* ---------- menu bar ---------- */\r\n.menubar {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 6px;\r\n  padding: 7px;\r\n  border-bottom: 1px solid var(--panel-edge);\r\n  background: linear-gradient(#e4e1d2, #d3cfbd);\r\n}\r\n\r\n.menubar__item {\r\n  padding: 7px 16px;\r\n  border: 2px outset #ece9da;\r\n  background: #ddd9c8;\r\n  color: var(--navy);\r\n  font-size: 0.66rem;\r\n  font-weight: bold;\r\n  letter-spacing: 0.14em;\r\n  text-decoration: none;\r\n}\r\n\r\n.menubar__item:hover,\r\n.menubar__item.is-current {\r\n  border-style: inset;\r\n  background: #cdc8b4;\r\n}\r\n\r\n/* ---------- admission ---------- */\r\n.admission {\r\n  padding: clamp(1rem, 4vw, 2rem) clamp(0.75rem, 4vw, 2rem) clamp(1.4rem, 4vw, 2.2rem);\r\n}\r\n\r\n.tank {\r\n  position: relative;\r\n  height: clamp(190px, 38vw, 300px);\r\n  overflow: hidden;\r\n  border: 2px inset #b9c8cc;\r\n  background: linear-gradient(#0d4256 0%, #06222c 74%, #041720 100%);\r\n}\r\n\r\n.tank__light {\r\n  position: absolute;\r\n  inset: -20% -10% 40%;\r\n  opacity: 0.5;\r\n  background:\r\n    repeating-linear-gradient(102deg, rgba(150, 233, 245, 0.18) 0 3px, transparent 3px 26px),\r\n    repeating-linear-gradient(78deg, rgba(150, 233, 245, 0.14) 0 2px, transparent 2px 34px);\r\n  filter: blur(1px);\r\n  animation: caustics 11s ease-in-out infinite alternate;\r\n}\r\n\r\n@keyframes caustics {\r\n  to { transform: translate3d(18px, 10px, 0) skewX(4deg); opacity: 0.78; }\r\n}\r\n\r\n.tank__swimmers {\r\n  position: absolute;\r\n  inset: 0;\r\n}\r\n\r\n.tank__fish {\r\n  position: absolute;\r\n  width: 76px;\r\n  height: auto;\r\n  fill: rgba(139, 196, 205, 0.22);\r\n  filter: blur(0.4px) drop-shadow(0 0 14px rgba(0, 0, 0, 0.45));\r\n}\r\n\r\n.tank__fish--a { top: 26%; animation: drift 26s linear infinite; }\r\n.tank__fish--b { top: 58%; width: 52px; animation: drift 38s linear infinite 6s; }\r\n.tank__fish--c { top: 76%; width: 110px; opacity: 0.6; animation: drift 54s linear infinite 15s; }\r\n\r\n@keyframes drift {\r\n  from { transform: translateX(-130px) scaleX(-1); }\r\n  to { transform: translateX(calc(100% + 780px)) scaleX(-1); }\r\n}\r\n\r\n.tank__caption {\r\n  position: absolute;\r\n  right: 8px;\r\n  bottom: 6px;\r\n  margin: 0;\r\n  color: rgba(196, 232, 238, 0.5);\r\n  font-family: var(--mono);\r\n  font-size: 0.56rem;\r\n  letter-spacing: 0.1em;\r\n}\r\n\r\n.admission__cta {\r\n  padding-top: clamp(1.4rem, 5vw, 2.4rem);\r\n  text-align: center;\r\n}\r\n\r\n.ticket-button {\r\n  width: min(100%, 440px);\r\n  padding: clamp(1rem, 4vw, 1.5rem) 1rem;\r\n  border: 4px outset #f0d68a;\r\n  background: linear-gradient(#e0b544, var(--brass));\r\n  color: #2a1f05;\r\n  cursor: pointer;\r\n  font-family: var(--sans);\r\n  font-size: clamp(1rem, 4.4vw, 1.5rem);\r\n  font-weight: bold;\r\n  letter-spacing: 0.24em;\r\n  text-indent: 0.24em;\r\n  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.28);\r\n}\r\n\r\n.ticket-button:hover,\r\n.ticket-button:focus-visible {\r\n  background: linear-gradient(#eec659, #c79c34);\r\n  outline: 0;\r\n}\r\n\r\n.ticket-button:active {\r\n  border-style: inset;\r\n  box-shadow: none;\r\n  transform: translateY(3px);\r\n}\r\n\r\n.admission__note {\r\n  margin: 1.1rem 0 0;\r\n  color: var(--ink-soft);\r\n  font-size: 0.62rem;\r\n  letter-spacing: 0.06em;\r\n}\r\n\r\n/* ---------- guide ---------- */\r\n.section-title {\r\n  margin: 0;\r\n  padding: 9px clamp(0.75rem, 4vw, 2rem);\r\n  border-top: 1px solid var(--panel-edge);\r\n  border-bottom: 1px solid var(--panel-edge);\r\n  background: linear-gradient(var(--navy), #10283f);\r\n  color: #fff;\r\n  font-family: var(--sans);\r\n  font-size: 0.68rem;\r\n  letter-spacing: 0.26em;\r\n}\r\n\r\n.guide__body {\r\n  padding: clamp(1.2rem, 4vw, 2rem) clamp(0.75rem, 4vw, 2rem);\r\n}\r\n\r\n.guide__body p {\r\n  max-width: 46ch;\r\n  margin: 0 0 0.9rem;\r\n  font-size: 0.78rem;\r\n}\r\n\r\n.guide__body p:first-child {\r\n  font-family: var(--serif);\r\n  font-size: clamp(1rem, 3.6vw, 1.3rem);\r\n}\r\n\r\n.guide__body p:nth-child(2) {\r\n  font-family: var(--serif);\r\n  font-size: clamp(1rem, 3.6vw, 1.3rem);\r\n  font-style: italic;\r\n}\r\n\r\n.guide__body p:last-child {\r\n  margin: 1.6rem 0 0;\r\n  padding-top: 1rem;\r\n  border-top: 1px dotted var(--panel-edge);\r\n  color: var(--ink-soft);\r\n  font-size: 0.7rem;\r\n}\r\n\r\n/* ---------- next opening ---------- */\r\n.opening {\r\n  margin: 0 clamp(0.75rem, 4vw, 2rem) clamp(1.5rem, 5vw, 2.4rem);\r\n  padding: clamp(1rem, 4vw, 1.6rem);\r\n  border: 2px groove #b9c8cc;\r\n  background: #e7e4d5;\r\n  text-align: center;\r\n}\r\n\r\n.opening p {\r\n  margin: 0;\r\n}\r\n\r\n.opening__label {\r\n  color: var(--teal);\r\n  font-size: 0.62rem;\r\n  font-weight: bold;\r\n  letter-spacing: 0.3em;\r\n  text-indent: 0.3em;\r\n}\r\n\r\n.opening__date {\r\n  margin-top: 0.5rem !important;\r\n  font-family: var(--serif);\r\n  font-size: clamp(1.2rem, 5vw, 1.9rem);\r\n  letter-spacing: 0.06em;\r\n}\r\n\r\n.opening__clock {\r\n  display: grid;\r\n  grid-template-columns: repeat(3, 1fr);\r\n  gap: clamp(6px, 2vw, 12px);\r\n  margin-top: 1.2rem;\r\n}\r\n\r\n.opening__unit {\r\n  padding: 0.7rem 0.2rem 0.5rem;\r\n  border: 2px inset #c3c0ae;\r\n  background: #0d1b1f;\r\n}\r\n\r\n.opening__unit b {\r\n  display: block;\r\n  color: #7fe3c6;\r\n  font-family: var(--mono);\r\n  font-size: clamp(1.5rem, 7vw, 2.4rem);\r\n  font-weight: bold;\r\n  line-height: 1;\r\n  text-shadow: 0 0 12px rgba(127, 227, 198, 0.45);\r\n}\r\n\r\n.opening__unit span {\r\n  display: block;\r\n  margin-top: 0.45rem;\r\n  color: rgba(180, 220, 214, 0.7);\r\n  font-size: 0.5rem;\r\n  letter-spacing: 0.16em;\r\n}\r\n\r\n.opening__state {\r\n  margin-top: 1rem !important;\r\n  color: var(--ink-soft);\r\n  font-size: 0.6rem;\r\n  letter-spacing: 0.16em;\r\n}\r\n\r\n/* ---------- colophon ---------- */\r\n.colophon {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 0.35rem 1.5rem;\r\n  padding: 0.9rem clamp(0.75rem, 4vw, 2rem);\r\n  border-top: 2px solid var(--panel-edge);\r\n  background: #e4e1d2;\r\n  color: var(--ink-soft);\r\n  font-size: 0.56rem;\r\n  letter-spacing: 0.1em;\r\n}\r\n\r\n.colophon p {\r\n  margin: 0;\r\n}\r\n\r\n.colophon__counter {\r\n  margin-left: auto !important;\r\n}\r\n\r\n.colophon__counter span {\r\n  padding: 2px 5px;\r\n  border: 1px solid #000;\r\n  background: #000;\r\n  color: #6fdc8c;\r\n  font-family: var(--mono);\r\n  letter-spacing: 0.18em;\r\n}\r\n\r\n/* ================================================================\r\n   VISITOR REGISTRATION\r\n   ================================================================ */\r\n.registration {\r\n  position: fixed;\r\n  z-index: 40;\r\n  inset: 0;\r\n  display: grid;\r\n  padding: clamp(0px, 3vw, 28px);\r\n  place-items: center;\r\n  background: rgba(4, 20, 27, 0.88);\r\n}\r\n\r\n.registration[hidden] {\r\n  display: none;\r\n}\r\n\r\n.registration__frame {\r\n  display: flex;\r\n  width: min(100%, 640px);\r\n  max-height: 100%;\r\n  flex-direction: column;\r\n  border: 3px ridge #9fb6bb;\r\n  background: var(--panel);\r\n  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.55);\r\n}\r\n\r\n.registration__head {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.9rem;\r\n  padding: 0.85rem clamp(0.75rem, 4vw, 1.5rem);\r\n  background: linear-gradient(var(--navy), #10283f);\r\n  color: #fff;\r\n}\r\n\r\n.registration__title {\r\n  margin: 0;\r\n  font-size: 0.66rem;\r\n  font-weight: bold;\r\n  letter-spacing: 0.22em;\r\n}\r\n\r\n.registration__progress {\r\n  margin: 0 0 0 auto;\r\n  color: #b9d6dd;\r\n  font-family: var(--mono);\r\n  font-size: 0.72rem;\r\n  letter-spacing: 0.12em;\r\n}\r\n\r\n.registration__close {\r\n  width: 26px;\r\n  height: 26px;\r\n  flex: 0 0 auto;\r\n  border: 2px outset #6f8ea8;\r\n  background: #2d557f;\r\n  color: #fff;\r\n  cursor: pointer;\r\n  font-size: 0.7rem;\r\n  line-height: 1;\r\n}\r\n\r\n.registration__close:hover {\r\n  background: #3d6c9c;\r\n}\r\n\r\n.registration__track {\r\n  height: 6px;\r\n  background: #d3cfbd;\r\n}\r\n\r\n.registration__track i {\r\n  display: block;\r\n  height: 100%;\r\n  background: linear-gradient(90deg, var(--teal), #4fb0a4);\r\n  transition: width 240ms ease;\r\n}\r\n\r\n.registration__body {\r\n  flex: 1 1 auto;\r\n  padding: clamp(1.2rem, 5vw, 2.2rem) clamp(0.85rem, 4vw, 2.2rem);\r\n  overflow-y: auto;\r\n}\r\n\r\n.question__text {\n  margin: 0 0 1.6rem;\n  font-family: var(--serif);\r\n  font-size: clamp(1.15rem, 4.6vw, 1.6rem);\r\n  line-height: 1.35;\n}\n\n.question__media {\n  width: min(100%, 390px);\n  margin: -0.45rem auto 1.4rem;\n  border: 2px inset #b9b6a4;\n  background: #bb1717;\n}\n\n.question__media img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: min(34vh, 285px);\n  object-fit: contain;\n}\n\r\n.option-list {\r\n  display: grid;\r\n  gap: 8px;\r\n}\r\n\r\n.option {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 0.8rem;\r\n  padding: 0.85rem 1rem;\r\n  border: 2px outset #e2dfd0;\r\n  background: #e9e6d8;\r\n  color: var(--ink);\r\n  cursor: pointer;\r\n  font-family: var(--sans);\r\n  font-size: 0.76rem;\r\n  letter-spacing: 0.1em;\r\n  text-align: left;\r\n}\r\n\r\n.option::before {\r\n  width: 13px;\r\n  height: 13px;\r\n  flex: 0 0 auto;\r\n  border: 2px inset #b9b6a4;\r\n  border-radius: 50%;\r\n  background: #fbfaf4;\r\n  content: '';\r\n}\r\n\r\n.option:hover {\r\n  background: #ddd9c8;\r\n}\r\n\r\n.option.is-chosen {\r\n  border-style: inset;\r\n  background: #d3e2e0;\r\n}\r\n\r\n.option.is-chosen::before {\r\n  background: radial-gradient(circle, var(--teal) 0 45%, #fbfaf4 46%);\r\n}\r\n\r\n.text-entry {\r\n  width: 100%;\r\n  padding: 0.8rem 0.7rem;\r\n  border: 2px inset #b9b6a4;\r\n  background: #fbfaf4;\r\n  color: var(--ink);\r\n  font-family: var(--sans);\r\n  font-size: 1rem;\r\n}\r\n\r\n.text-entry:focus {\r\n  outline: 2px solid var(--teal);\r\n  outline-offset: 1px;\r\n}\r\n\r\n.field-hint {\r\n  margin: 0.8rem 0 0;\r\n  color: var(--ink-soft);\r\n  font-size: 0.6rem;\r\n  letter-spacing: 0.08em;\r\n}\r\n\r\n.field-hint[data-state='error'] {\r\n  color: #8b1e16;\r\n}\r\n\r\n.registration__foot[hidden] {\r\n  display: none;\r\n}\r\n\r\n.registration__foot {\r\n  display: flex;\r\n  gap: 10px;\r\n  padding: 0.9rem clamp(0.85rem, 4vw, 2.2rem) 1.1rem;\r\n  border-top: 1px solid var(--panel-edge);\r\n  background: #e4e1d2;\r\n}\r\n\r\n.flat-button {\r\n  min-width: 116px;\r\n  padding: 0.8rem 1.1rem;\r\n  border: 2px outset #ece9da;\r\n  background: #ddd9c8;\r\n  color: var(--navy);\r\n  cursor: pointer;\r\n  font-family: var(--sans);\r\n  font-size: 0.66rem;\r\n  font-weight: bold;\r\n  letter-spacing: 0.16em;\r\n}\r\n\r\n.flat-button:hover:not(:disabled) {\r\n  background: #cdc8b4;\r\n}\r\n\r\n.flat-button:disabled {\r\n  color: #9a978a;\r\n  cursor: not-allowed;\r\n  opacity: 0.7;\r\n}\r\n\r\n.flat-button--primary {\r\n  margin-left: auto;\r\n  border-color: #79c3bb;\r\n  background: linear-gradient(var(--teal), #14535c);\r\n  color: #fff;\r\n}\r\n\r\n.flat-button--primary:hover:not(:disabled) {\r\n  background: linear-gradient(#2b8793, #176069);\r\n}\r\n\r\n/* ---------- issuing ---------- */\r\n.issuing {\r\n  padding: clamp(2rem, 9vw, 4rem) 0;\r\n  text-align: center;\r\n}\r\n\r\n.issuing__complete {\r\n  margin: 0;\r\n  font-family: var(--serif);\r\n  font-size: clamp(1.3rem, 5vw, 1.8rem);\r\n  letter-spacing: 0.08em;\r\n}\r\n\r\n.issuing__status {\r\n  margin: 1.4rem 0 0;\r\n  color: var(--ink-soft);\r\n  font-family: var(--mono);\r\n  font-size: 0.8rem;\r\n  letter-spacing: 0.16em;\r\n}\r\n\r\n.issuing__status i {\r\n  animation: issuing-dot 1.1s steps(4, end) infinite;\r\n}\r\n\r\n@keyframes issuing-dot {\r\n  0% { opacity: 0.2; }\r\n  50% { opacity: 1; }\r\n}\r\n\r\n/* ---------- ticket ---------- */\r\n.ticket {\r\n  margin: 0 auto;\r\n  width: min(100%, 420px);\r\n  border: 2px solid var(--ink);\r\n  background:\r\n    repeating-linear-gradient(90deg, rgba(28, 28, 25, 0.035) 0 1px, transparent 1px 6px),\r\n    #f7f5eb;\r\n  box-shadow: 6px 6px 0 rgba(23, 56, 92, 0.22);\r\n}\r\n\r\n.ticket__head {\r\n  padding: 1rem;\r\n  border-bottom: 2px solid var(--ink);\r\n  background: linear-gradient(var(--navy), var(--teal));\r\n  color: #fff;\r\n  text-align: center;\r\n}\r\n\r\n.ticket__mark {\r\n  margin: 0;\r\n  font-family: var(--serif);\r\n  font-size: clamp(1.5rem, 7vw, 2.1rem);\r\n  letter-spacing: 0.28em;\r\n  text-indent: 0.28em;\r\n}\r\n\r\n.ticket__sub {\r\n  margin: 0.5rem 0 0;\r\n  font-size: 0.56rem;\r\n  letter-spacing: 0.3em;\r\n  text-indent: 0.3em;\r\n}\r\n\r\n.ticket__fields {\r\n  margin: 0;\r\n  padding: 1.1rem 1.2rem 0.4rem;\r\n}\r\n\r\n.ticket__fields div {\r\n  padding: 0.6rem 0;\r\n  border-bottom: 1px dotted var(--panel-edge);\r\n}\r\n\r\n.ticket__fields dt {\r\n  color: var(--ink-soft);\r\n  font-size: 0.52rem;\r\n  letter-spacing: 0.2em;\r\n}\r\n\r\n.ticket__fields dd {\r\n  margin: 0.35rem 0 0;\r\n  font-family: var(--mono);\r\n  font-size: clamp(0.9rem, 3.6vw, 1.15rem);\r\n  letter-spacing: 0.08em;\r\n  word-break: break-word;\r\n}\r\n\r\n.ticket__foot {\r\n  padding: 0.9rem 1.2rem 1.1rem;\r\n  color: var(--ink-soft);\r\n  font-size: 0.56rem;\r\n  letter-spacing: 0.12em;\r\n  text-align: center;\r\n}\r\n\r\n.ticket-actions {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 10px;\r\n  justify-content: center;\r\n  padding-top: 1.6rem;\r\n}\r\n\r\n@media (max-width: 430px) {\r\n  body { padding: 0; }\r\n  .page { border-width: 0 0 3px; }\r\n  .menubar__item { flex: 1 1 auto; text-align: center; }\r\n  .colophon { font-size: 0.52rem; }\r\n  .colophon__counter { margin-left: 0 !important; }\r\n  .registration__frame { height: 100%; border: 0; }\r\n  .flat-button { min-width: 0; flex: 1 1 0; }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n  *,\r\n  *::before,\r\n  *::after {\r\n    animation-duration: 0.01ms !important;\r\n    animation-iteration-count: 1 !important;\r\n    transition-duration: 0.01ms !important;\r\n  }\r\n}\r\n","type":"text/css; charset=utf-8"},"/aquarium/script.js":{"body":"/* ================================================================\r\n   AQUARIUM CONFIGURATION — THE VALUES PLAYTESTS NEED TO SWAP\r\n   ================================================================ */\r\nconst CONFIG = {\r\n  /* Playtest opening is fixed. A real lunar cycle can replace this later. */\r\n  openingDate: '2026-09-26T00:00:00-04:00',\r\n  openingLabel: 'SEPTEMBER 26, 2026',\r\n  ticketNumber: '9A7F-2C1B',\r\n  /* Every visitor is COMPLETE for now; the questionnaire does not branch yet. */\r\n  visitorClass: 'COMPLETE',\r\n};\r\n\r\nconst STORAGE_KEY = 'aquarium-visitor';\r\nconst SECOND = 1000;\r\nconst MINUTE = 60 * SECOND;\r\nconst HOUR = 60 * MINUTE;\r\nconst DAY = 24 * HOUR;\r\n\r\nconst store = {\r\n  read() {\r\n    try {\r\n      return JSON.parse(window.localStorage.getItem(STORAGE_KEY) ?? '{}');\r\n    } catch {\r\n      return {};\r\n    }\r\n  },\r\n  write(patch) {\r\n    try {\r\n      window.localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...store.read(), ...patch }));\r\n    } catch {\r\n      /* Storage unavailable — the visit still works, it just is not remembered. */\r\n    }\r\n  },\r\n  clear() {\r\n    try {\r\n      window.localStorage.removeItem(STORAGE_KEY);\r\n    } catch {\r\n      /* Nothing to clear. */\r\n    }\r\n  },\r\n};\r\n\r\nif (new URLSearchParams(location.search).get('reset') === 'true') {\r\n  store.clear();\r\n  history.replaceState(null, '', location.pathname + location.hash);\r\n}\r\n\r\nfunction pad(value, size = 2) {\r\n  return String(value).padStart(size, '0');\r\n}\r\n\r\n/* ================================================================\r\n   NEXT OPENING COUNTDOWN\r\n   ================================================================ */\r\nconst openingDate = document.querySelector('#opening-date');\r\nconst openingDays = document.querySelector('#opening-days');\r\nconst openingHours = document.querySelector('#opening-hours');\r\nconst openingMinutes = document.querySelector('#opening-minutes');\r\nconst openingState = document.querySelector('#opening-state');\r\nconst openingClock = document.querySelector('#opening-clock');\r\n\r\nopeningDate.textContent = CONFIG.openingLabel;\r\n\r\nfunction updateOpeningCountdown() {\r\n  const remaining = new Date(CONFIG.openingDate).getTime() - Date.now();\r\n\r\n  if (remaining <= 0) {\r\n    openingDays.textContent = '00';\r\n    openingHours.textContent = '00';\r\n    openingMinutes.textContent = '00';\r\n    openingState.textContent = 'THE AQUARIUM IS OPEN';\r\n    openingClock.setAttribute('aria-label', 'The Aquarium is open');\r\n    return;\r\n  }\r\n\r\n  const days = Math.floor(remaining / DAY);\r\n  const hours = Math.floor((remaining % DAY) / HOUR);\r\n  const minutes = Math.floor((remaining % HOUR) / MINUTE);\r\n\r\n  openingDays.textContent = pad(days);\r\n  openingHours.textContent = pad(hours);\r\n  openingMinutes.textContent = pad(minutes);\r\n  openingState.textContent = 'CLOSED UNTIL THE FULL MOON';\r\n  openingClock.setAttribute('aria-label', `${days} days, ${hours} hours and ${minutes} minutes until the next opening`);\r\n}\r\n\r\nupdateOpeningCountdown();\r\nwindow.setInterval(updateOpeningCountdown, SECOND);\r\n\r\n/* The counter has been climbing since the page was last touched in 2008. */\r\nconst visitorCounter = document.querySelector('#visitor-counter');\r\nconst daysSinceLastUpdate = Math.floor((Date.now() - Date.parse('2008-10-18T00:00:00-04:00')) / DAY);\r\nvisitorCounter.textContent = pad(14_219 + daysSinceLastUpdate * 3, 7);\r\n\r\n/* ================================================================\r\n   VISITOR REGISTRATION QUESTIONNAIRE\r\n   ================================================================ */\r\nconst QUESTIONS = [\r\n  { id: 'name', type: 'text', text: 'What name would you like to be registered under?', placeholder: 'Name', hint: 'This name is printed on your ticket.' },\r\n  { id: 'age', type: 'number', text: 'How old are you?', placeholder: 'Age' },\r\n  { id: 'visitedBefore', type: 'choice', text: 'Have you visited this aquarium before?', options: ['YES', 'NO', \"I'M NOT SURE\"] },\r\n  { id: 'alone', type: 'choice', text: 'Are you visiting alone?', options: ['YES', 'NO'] },\r\n  { id: 'recognize', type: 'choice', text: 'Do you usually recognize yourself immediately when you look into a mirror?', options: ['ALWAYS', 'USUALLY', 'SOMETIMES', 'RARELY'] },\n  { id: 'unfamiliar', type: 'choice', text: 'Have you ever felt that your reflection looked unfamiliar to you?', options: ['YES', 'NO', \"I'M NOT SURE\"] },\n  { id: 'heartSide', type: 'choice', text: 'Is your heart on the right side of your body?', options: ['YES', 'NO', \"I'M NOT SURE\"] },\n  { id: 'unexpected', type: 'choice', text: 'Have you ever noticed your reflection doing something you did not expect?', options: ['YES', 'NO', \"I'M NOT SURE\"] },\n  { id: 'clockDirection', type: 'choice', text: 'Is this clock moving clockwise or counterclockwise?', image: '../assets/clock.gif', imageAlt: 'An animated clock face', options: ['CLOCKWISE', 'COUNTERCLOCKWISE', \"I'M NOT SURE\"] },\n  { id: 'someoneElse', type: 'choice', text: 'Have you ever seen someone in a mirror who you believed was not yourself?', options: ['YES', 'NO', \"I'M NOT SURE\"] },\n  { id: 'double', type: 'choice', text: 'Do you believe there is another person who is exactly like you somewhere in the world?', options: ['YES', 'NO', \"I DON'T KNOW\"] },\r\n  { id: 'identical', type: 'choice', text: 'If you met someone identical to you, would you consider them to be you?', options: ['YES', 'NO', 'IT DEPENDS'] },\r\n  { id: 'consent', type: 'choice', text: 'Do you consent to your visitor record being preserved by the Aquarium?', options: ['YES', 'NO'] },\r\n];\r\n\r\nconst registration = document.querySelector('#registration');\r\nconst registrationBody = document.querySelector('#registration-body');\r\nconst registrationFoot = document.querySelector('#registration-foot');\r\nconst registrationProgress = document.querySelector('#registration-progress');\r\nconst registrationBar = document.querySelector('#registration-bar');\r\nconst registrationBack = document.querySelector('#registration-back');\r\nconst registrationNext = document.querySelector('#registration-next');\r\nconst registrationClose = document.querySelector('#registration-close');\r\nconst getTicketButton = document.querySelector('#get-ticket');\r\n\r\nlet answers = store.read().answers ?? {};\r\nlet questionIndex = 0;\r\n\r\nfunction setProgress(step) {\r\n  registrationProgress.textContent = `${pad(step)} / ${pad(QUESTIONS.length)}`;\r\n  registrationBar.style.width = `${(step / QUESTIONS.length) * 100}%`;\r\n}\r\n\r\nfunction currentAnswer() {\r\n  return answers[QUESTIONS[questionIndex].id];\r\n}\r\n\r\nfunction saveAnswer(value) {\r\n  answers = { ...answers, [QUESTIONS[questionIndex].id]: value };\r\n  store.write({ answers, visitorClass: CONFIG.visitorClass });\r\n}\r\n\r\nfunction renderQuestion() {\r\n  const question = QUESTIONS[questionIndex];\r\n  setProgress(questionIndex + 1);\r\n  registrationFoot.hidden = false;\r\n  registrationBack.disabled = questionIndex === 0;\r\n  registrationNext.textContent = questionIndex === QUESTIONS.length - 1 ? 'SUBMIT' : 'CONTINUE';\r\n\r\n  const text = document.createElement('p');\r\n  text.className = 'question__text';\r\n  text.textContent = question.text;\r\n\r\n  const nodes = [text];\n\n  if (question.image) {\n    const media = document.createElement('figure');\n    media.className = 'question__media';\n    const image = document.createElement('img');\n    image.src = question.image;\n    image.alt = question.imageAlt ?? '';\n    media.append(image);\n    nodes.push(media);\n  }\n\r\n  if (question.type === 'choice') {\r\n    const list = document.createElement('div');\r\n    list.className = 'option-list';\r\n    question.options.forEach((option) => {\r\n      const button = document.createElement('button');\r\n      button.className = `option${currentAnswer() === option ? ' is-chosen' : ''}`;\r\n      button.type = 'button';\r\n      button.textContent = option;\r\n      button.addEventListener('click', () => {\r\n        saveAnswer(option);\r\n        list.querySelectorAll('.option').forEach((node) => node.classList.toggle('is-chosen', node === button));\r\n        registrationNext.disabled = false;\r\n      });\r\n      list.append(button);\r\n    });\r\n    nodes.push(list);\r\n    registrationNext.disabled = currentAnswer() === undefined;\r\n  } else {\r\n    const input = document.createElement('input');\r\n    input.className = 'text-entry';\r\n    input.id = 'question-entry';\r\n    input.type = question.type === 'number' ? 'number' : 'text';\r\n    input.placeholder = question.placeholder ?? '';\r\n    input.value = currentAnswer() ?? '';\r\n    input.autocomplete = 'off';\r\n    if (question.type === 'number') {\r\n      input.inputMode = 'numeric';\r\n      input.min = '0';\r\n      input.max = '130';\r\n    } else {\r\n      input.maxLength = 40;\r\n    }\r\n    input.addEventListener('input', () => {\r\n      hint.removeAttribute('data-state');\r\n      hint.textContent = question.hint ?? '';\r\n      registrationNext.disabled = input.value.trim() === '';\r\n    });\r\n    input.addEventListener('keydown', (event) => {\r\n      if (event.key === 'Enter') {\r\n        event.preventDefault();\r\n        registrationNext.click();\r\n      }\r\n    });\r\n\r\n    const hint = document.createElement('p');\r\n    hint.className = 'field-hint';\r\n    hint.textContent = question.hint ?? '';\r\n\r\n    nodes.push(input, hint);\r\n    registrationNext.disabled = (currentAnswer() ?? '').toString().trim() === '';\r\n  }\r\n\r\n  registrationBody.replaceChildren(...nodes);\r\n  registrationBody.scrollTop = 0;\r\n  window.setTimeout(() => registrationBody.querySelector('#question-entry')?.focus({ preventScroll: true }), 30);\r\n}\r\n\r\nfunction advance() {\r\n  const question = QUESTIONS[questionIndex];\r\n\r\n  if (question.type !== 'choice') {\r\n    const input = registrationBody.querySelector('#question-entry');\r\n    const value = input.value.trim();\r\n    const hint = registrationBody.querySelector('.field-hint');\r\n\r\n    if (!value) {\r\n      hint.textContent = 'Please answer before continuing.';\r\n      hint.dataset.state = 'error';\r\n      input.focus();\r\n      return;\r\n    }\r\n    saveAnswer(value);\r\n  }\r\n\r\n  if (questionIndex === QUESTIONS.length - 1) {\r\n    issueTicket();\r\n    return;\r\n  }\r\n\r\n  questionIndex += 1;\r\n  renderQuestion();\r\n}\r\n\r\nregistrationNext.addEventListener('click', advance);\r\nregistrationBack.addEventListener('click', () => {\r\n  if (questionIndex === 0) return;\r\n  questionIndex -= 1;\r\n  renderQuestion();\r\n});\r\n\r\n/* ================================================================\r\n   TICKET\r\n   ================================================================ */\r\nfunction visitorName() {\r\n  return (store.read().visitorName ?? answers.name ?? 'VISITOR').toString().toUpperCase();\r\n}\r\n\r\nfunction ticketFields() {\r\n  return [\r\n    ['VISITOR', visitorName()],\r\n    ['TICKET NO.', CONFIG.ticketNumber],\r\n    ['STATUS', 'VALID'],\r\n    ['ENTRY CONDITION', 'FULL MOON'],\r\n  ];\r\n}\r\n\r\nfunction renderTicket() {\r\n  setProgress(QUESTIONS.length);\r\n  registrationFoot.hidden = true;\r\n\r\n  const ticket = document.createElement('article');\r\n  ticket.className = 'ticket';\r\n\r\n  const head = document.createElement('header');\r\n  head.className = 'ticket__head';\r\n  head.innerHTML = '<p class=\"ticket__mark\">AQUARIUM</p><p class=\"ticket__sub\">VISITOR ADMISSION</p>';\r\n\r\n  const fields = document.createElement('dl');\r\n  fields.className = 'ticket__fields';\r\n  fields.innerHTML = ticketFields()\r\n    .map(([label, value]) => `<div><dt>${label}</dt><dd>${value}</dd></div>`)\r\n    .join('');\r\n\r\n  const foot = document.createElement('p');\r\n  foot.className = 'ticket__foot';\r\n  foot.textContent = 'KEEP THIS TICKET. YOU MAY NEED IT LATER.';\r\n\r\n  ticket.append(head, fields, foot);\r\n\r\n  const actions = document.createElement('div');\r\n  actions.className = 'ticket-actions';\r\n\r\n  const save = document.createElement('button');\r\n  save.className = 'flat-button flat-button--primary';\r\n  save.type = 'button';\r\n  save.textContent = 'SAVE TICKET';\r\n  save.addEventListener('click', () => saveTicketImage(save));\r\n\r\n  const done = document.createElement('button');\r\n  done.className = 'flat-button';\r\n  done.type = 'button';\r\n  done.textContent = 'CLOSE';\r\n  done.addEventListener('click', closeRegistration);\r\n\r\n  const again = document.createElement('button');\r\n  again.className = 'flat-button';\r\n  again.type = 'button';\r\n  again.textContent = 'REGISTER AGAIN';\r\n  again.addEventListener('click', () => {\r\n    answers = {};\r\n    questionIndex = 0;\r\n    store.clear();\r\n    renderQuestion();\r\n  });\r\n\r\n  actions.append(save, done, again);\r\n  registrationBody.replaceChildren(ticket, actions);\r\n  registrationBody.scrollTop = 0;\r\n}\r\n\r\nfunction issueTicket() {\r\n  registrationFoot.hidden = true;\r\n  setProgress(QUESTIONS.length);\r\n  store.write({\r\n    answers,\r\n    visitorName: answers.name ?? 'VISITOR',\r\n    visitorClass: CONFIG.visitorClass,\r\n    ticketIssued: true,\r\n  });\r\n\r\n  const issuing = document.createElement('div');\r\n  issuing.className = 'issuing';\r\n  issuing.innerHTML =\r\n    '<p class=\"issuing__complete\">REGISTRATION COMPLETE</p><p class=\"issuing__status\">GENERATING TICKET<i>...</i></p>';\r\n  registrationBody.replaceChildren(issuing);\r\n\r\n  window.setTimeout(renderTicket, 1700);\r\n}\r\n\r\n/* The ticket is redrawn on a canvas rather than screenshotted, so the export\r\n   does not depend on any rendering library. */\r\nfunction drawTicket() {\r\n  const width = 760;\r\n  const height = 1040;\r\n  const scale = 2;\r\n  const canvas = document.createElement('canvas');\r\n  canvas.width = width * scale;\r\n  canvas.height = height * scale;\r\n  const context = canvas.getContext('2d');\r\n  context.scale(scale, scale);\r\n\r\n  context.fillStyle = '#f7f5eb';\r\n  context.fillRect(0, 0, width, height);\r\n\r\n  for (let x = 0; x < width; x += 6) {\r\n    context.fillStyle = 'rgba(28,28,25,0.035)';\r\n    context.fillRect(x, 0, 1, height);\r\n  }\r\n\r\n  const header = context.createLinearGradient(0, 0, 0, 230);\r\n  header.addColorStop(0, '#17385c');\r\n  header.addColorStop(1, '#1f6f7a');\r\n  context.fillStyle = header;\r\n  context.fillRect(0, 0, width, 230);\r\n\r\n  context.textAlign = 'center';\r\n  context.fillStyle = '#ffffff';\r\n  context.font = '70px \"Times New Roman\", Times, serif';\r\n  context.letterSpacing = '20px';\r\n  context.fillText('AQUARIUM', width / 2 + 10, 130);\r\n  context.font = '18px Verdana, Geneva, sans-serif';\r\n  context.letterSpacing = '10px';\r\n  context.fillText('VISITOR ADMISSION', width / 2 + 5, 180);\r\n\r\n  context.textAlign = 'left';\r\n  context.letterSpacing = '0px';\r\n  let y = 310;\r\n  ticketFields().forEach(([label, value]) => {\r\n    context.fillStyle = '#5c5c52';\r\n    context.font = '17px Verdana, Geneva, sans-serif';\r\n    context.letterSpacing = '6px';\r\n    context.fillText(label, 70, y);\r\n\r\n    context.fillStyle = '#1c1c19';\r\n    context.font = '36px \"Courier New\", Courier, monospace';\r\n    context.letterSpacing = '2px';\r\n    context.fillText(value, 70, y + 52);\r\n\r\n    context.letterSpacing = '0px';\r\n    context.strokeStyle = '#c8c4b0';\r\n    context.setLineDash([2, 5]);\r\n    context.beginPath();\r\n    context.moveTo(70, y + 92);\r\n    context.lineTo(width - 70, y + 92);\r\n    context.stroke();\r\n    context.setLineDash([]);\r\n\r\n    y += 150;\r\n  });\r\n\r\n  context.textAlign = 'center';\r\n  context.fillStyle = '#5c5c52';\r\n  context.font = '16px Verdana, Geneva, sans-serif';\r\n  context.letterSpacing = '4px';\r\n  context.fillText('KEEP THIS TICKET. YOU MAY NEED IT LATER.', width / 2, height - 70);\r\n\r\n  context.letterSpacing = '0px';\r\n  context.strokeStyle = '#1c1c19';\r\n  context.lineWidth = 4;\r\n  context.strokeRect(2, 2, width - 4, height - 4);\r\n\r\n  return canvas;\r\n}\r\n\r\nfunction saveTicketImage(button) {\r\n  const label = button.textContent;\r\n  try {\r\n    const link = document.createElement('a');\r\n    link.href = drawTicket().toDataURL('image/png');\r\n    link.download = `aquarium-ticket-${visitorName().toLowerCase().replace(/[^a-z0-9]+/g, '-')}.png`;\r\n    link.click();\r\n    button.textContent = 'SAVED';\r\n  } catch {\r\n    button.textContent = 'SCREENSHOT INSTEAD';\r\n  }\r\n  window.setTimeout(() => {\r\n    button.textContent = label;\r\n  }, 2400);\r\n}\r\n\r\n/* ================================================================\r\n   OVERLAY CONTROL\r\n   ================================================================ */\r\nfunction openRegistration() {\r\n  registration.hidden = false;\r\n  document.body.style.overflow = 'hidden';\r\n\r\n  if (store.read().ticketIssued) {\r\n    renderTicket();\r\n    return;\r\n  }\r\n\r\n  questionIndex = 0;\r\n  renderQuestion();\r\n}\r\n\r\nfunction closeRegistration() {\r\n  registration.hidden = true;\r\n  document.body.style.overflow = '';\r\n  getTicketButton.focus({ preventScroll: true });\r\n}\r\n\r\ngetTicketButton.addEventListener('click', openRegistration);\r\nregistrationClose.addEventListener('click', closeRegistration);\r\ndocument.addEventListener('keydown', (event) => {\r\n  if (event.key === 'Escape' && !registration.hidden) closeRegistration();\r\n});\r\n\r\nif (store.read().ticketIssued) getTicketButton.textContent = 'VIEW YOUR TICKET';\r\n\r\n/* ---------- menu bar highlighting ---------- */\r\nconst menuItems = [...document.querySelectorAll('.menubar__item')];\r\nconst sections = menuItems.map((item) => document.querySelector(item.getAttribute('href')));\r\nconst sectionObserver = new IntersectionObserver(\r\n  (entries) => {\r\n    entries\r\n      .filter((entry) => entry.isIntersecting)\r\n      .forEach((entry) => {\r\n        menuItems.forEach((item, index) => item.classList.toggle('is-current', sections[index] === entry.target));\r\n      });\r\n  },\r\n  { rootMargin: '-40% 0px -50% 0px' },\r\n);\r\nsections.forEach((section) => section && sectionObserver.observe(section));\r\n","type":"text/javascript; charset=utf-8"},"/robots.txt":{"body":"User-agent: *\r\nAllow: /\r\nDisallow: /aquarium\r\n\r\nSitemap: https://etcweatherobservation.com/sitemap.xml\r\n","type":"text/plain; charset=utf-8"},"/sitemap.xml":{"body":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\r\n  <url>\r\n    <loc>https://etcweatherobservation.com/</loc>\r\n    <lastmod>2026-08-31</lastmod>\r\n    <changefreq>daily</changefreq>\r\n    <priority>1.0</priority>\r\n  </url>\r\n</urlset>\r\n","type":"application/xml; charset=utf-8"}};
const binaryAssets = {"/icon_black.ico":{"body":"","type":"image/x-icon"},"/icon_white.ico":{"body":"","type":"image/x-icon"},"/fish_black.png":{"body":"","type":"image/png"},"/og.png":{"body":"","type":"image/png"},"/assets/clock.gif":{"body":"","type":"image/gif"},"/packets/packet-0003-1.png":{"body":"","type":"image/png"},"/packets/packet-0004-1.png":{"body":"","type":"image/png"},"/packets/packet-0005-1.png":{"body":"","type":"image/png"},"/packets/packet-0006-1.png":{"body":"","type":"image/png"},"/packets/packet-0006-2.png":{"body":"","type":"image/png"},"/packets/packet-0007-1.png":{"body":"","type":"image/png"},"/packets/packet-0007-2.png":{"body":"","type":"image/png"},"/packets/packet-0008-1.png":{"body":"","type":"image/png"}};

function decodeBase64(value) {
  const raw = atob(value);
  const bytes = new Uint8Array(raw.length);
  for (let index = 0; index < raw.length; index += 1) bytes[index] = raw.charCodeAt(index);
  return bytes;
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname;
    const textAsset = textAssets[path];
    if (textAsset) {
      return new Response(request.method === 'HEAD' ? null : textAsset.body, {
        status: 200,
        headers: { 'content-type': textAsset.type, 'cache-control': textAsset.type.startsWith('text/html') ? 'no-cache' : 'public, max-age=3600' },
      });
    }
    const binaryAsset = binaryAssets[path];
    if (binaryAsset) {
      return new Response(request.method === 'HEAD' ? null : decodeBase64(binaryAsset.body), {
        status: 200,
        headers: { 'content-type': binaryAsset.type, 'cache-control': 'public, max-age=86400' },
      });
    }
    if (request.method === 'GET' && request.headers.get('accept')?.includes('text/html')) {
      const fallback = path.startsWith('/aquarium') ? textAssets['/aquarium/'] : textAssets['/'];
      return new Response(fallback.body, { status: 200, headers: { 'content-type': fallback.type, 'cache-control': 'no-cache' } });
    }
    return new Response('NOT FOUND', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8' } });
  },
};
